// ═══════════════════════════════════════════════════════════════
//  Morgan.stdio: comic website for Cloudflare Workers
//  Database: Cloudflare D1 (binding "DB")
//  Files (PDFs, covers): Cloudflare R2 (binding "FILES")
//  Admin password: secret "ADMIN_PASSWORD" (set in Cloudflare dashboard)
// ═══════════════════════════════════════════════════════════════

const PLANS = {
  monthly: { id: 'monthly', name: 'Monthly', price: 2, currency: 'USD', days: 30, methods: ['card', 'paypal'], label: '$2', per: 'month' },
  yearly: { id: 'yearly', name: 'Yearly', price: 12, currency: 'USD', days: 365, methods: ['card', 'paypal'], label: '$12', per: 'year', badge: 'Save 50%' },
  momo: { id: 'momo', name: 'Mobile Money', price: 500, currency: 'XAF', days: 30, methods: ['mtn', 'orange'], label: '500 CFA', per: 'month', badge: 'MTN & Orange' },
};
const METHODS = {
  mtn: { id: 'mtn', name: 'MTN Mobile Money', needsPhone: true },
  orange: { id: 'orange', name: 'Orange Money', needsPhone: true },
  card: { id: 'card', name: 'Visa / Mastercard', needsPhone: false },
  paypal: { id: 'paypal', name: 'PayPal', needsPhone: false },
};
const MAX_UPLOAD = 100 * 1024 * 1024; // Cloudflare free plan request limit
const PBKDF2_ITER = 10000;            // fits the free plan's CPU limit

// ── Website pages ──
const PAGES = {"/account.html": {"type": "text/html; charset=utf-8", "body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>My Account · Morgan.stdio</title>\n<link rel=\"icon\" href=\"/logo.svg\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n<nav id=\"nav\"></nav>\n<main class=\"wrap\" style=\"max-width:820px;padding:3rem 0\" id=\"main\"></main>\n<footer id=\"footer\"></footer>\n<script src=\"/app.js\"></script>\n<script>\n(async () => {\n  const u = await boot();\n  if (!u) return location.href = '/login?next=/account';\n  const main = document.getElementById('main');\n  const pays = await api('/api/me/payments');\n  const sub = u.subscription;\n  main.innerHTML = `\n    <h1 class=\"display\" style=\"font-size:2.8rem\">My Account</h1>\n    <p class=\"muted\" style=\"margin-bottom:2rem\">${esc(u.name)} · ${esc(u.email)}</p>\n\n    <div class=\"panel\" style=\"margin-bottom:1.5rem\">\n      <h2 style=\"font-size:1.2rem;margin-bottom:.8rem\">Subscription</h2>\n      ${u.role === 'admin' ? `<p><span class=\"status active\">Admin</span> You have full access to every comic. <a href=\"/admin\" style=\"color:var(--yellow)\">Open dashboard →</a></p>`\n        : u.subscribed ? `<p><span class=\"status active\">Active</span> ${esc(sub.planName)} plan, valid until <b>${fmtDate(sub.expiresAt)}</b></p>\n             <a href=\"/subscribe\" class=\"btn ghost sm\" style=\"margin-top:1rem\">Add more time</a>`\n        : `<p><span class=\"status none\">Not subscribed</span> ${sub ? `Your plan ended on ${fmtDate(sub.expiresAt)}.` : 'Subscribe to unlock every chapter.'}</p>\n             <a href=\"/subscribe\" class=\"btn yellow\" style=\"margin-top:1rem\">Subscribe · from $2 or 500 CFA</a>`}\n    </div>\n\n    ${u.role !== 'admin' ? `<div class=\"panel\" style=\"margin-bottom:1.5rem\">\n      <h2 style=\"font-size:1.2rem;margin-bottom:.8rem\">Payment history</h2>\n      ${pays.length ? `<div class=\"table-wrap\"><table><tr><th>Date</th><th>Plan</th><th>Method</th><th>Amount</th><th>Status</th></tr>\n        ${pays.map(p => `<tr><td>${fmtDate(p.createdAt)}</td><td>${esc(p.planName)}</td><td>${esc(p.methodName)}</td><td>${money(p.amount, p.currency)}</td><td><span class=\"status ${p.status}\">${p.status}</span></td></tr>`).join('')}\n      </table></div>` : '<p class=\"muted\">No payments yet.</p>'}\n    </div>` : ''}\n\n    <div class=\"panel\">\n      <h2 style=\"font-size:1.2rem;margin-bottom:.8rem\">Change password</h2>\n      <div id=\"pwMsg\"></div>\n      <form id=\"pw\"><div class=\"row\">\n        <div class=\"field\"><label>Current password</label><input type=\"password\" name=\"current\" required autocomplete=\"current-password\"></div>\n        <div class=\"field\"><label>New password</label><input type=\"password\" name=\"newPassword\" required minlength=\"6\" autocomplete=\"new-password\"></div>\n      </div><button class=\"btn\">Update password</button></form>\n    </div>\n    <p style=\"margin-top:1.5rem\"><a href=\"#\" onclick=\"logout();return false\" class=\"muted\">Log out</a></p>`;\n\n  document.getElementById('pw').onsubmit = async e => {\n    e.preventDefault();\n    const f = e.target, m = document.getElementById('pwMsg');\n    try { await api('/api/me/password', { body: { current: f.current.value, newPassword: f.newPassword.value } }); m.innerHTML = '<div class=\"success\">Password updated.</div>'; f.reset(); }\n    catch (err) { m.innerHTML = `<div class=\"error\">${esc(err.message)}</div>`; }\n  };\n})();\n</script>\n</body>\n</html>\n"}, "/admin.html": {"type": "text/html; charset=utf-8", "body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Admin Dashboard · Morgan.stdio</title>\n<link rel=\"icon\" href=\"/logo.svg\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n<nav id=\"nav\"></nav>\n<main class=\"wrap\" style=\"padding:2.5rem 0\" id=\"main\"><div class=\"spinner\" style=\"margin:8rem auto\"></div></main>\n<footer id=\"footer\"></footer>\n<script src=\"/app.js\"></script>\n<script>\nlet comics = [];\nconst MAX_MB = 100;\n\n// Load a picture for processing (works with HEIC/JPEG/PNG on iPhone)\nconst loadBitmap = file => new Promise((res, rej) => {\n  (window.createImageBitmap ? createImageBitmap(file) : Promise.reject())\n    .then(res, () => { const u = URL.createObjectURL(file); const im = new Image(); im.onload = () => res(im); im.onerror = rej; im.src = u; });\n});\n\n// One long picture -> split into 4000px parts so phones scroll smoothly without blur\nasync function sliceLongStrip(file) {\n  let bm; try { bm = await loadBitmap(file); } catch (e) { return null; }\n  const w = bm.width || bm.naturalWidth, h = bm.height || bm.naturalHeight;\n  if (h < 5000 || h / w < 1.7) return null;              // not a long strip\n  const CH = 4000, parts = Math.ceil(h / CH), out = [];\n  for (let i = 0; i < parts; i++) {\n    const ph = Math.min(CH, h - i * CH);\n    const cv = document.createElement('canvas'); cv.width = w; cv.height = ph;\n    const cx = cv.getContext('2d');\n    cx.fillStyle = '#fff'; cx.fillRect(0, 0, w, ph);\n    cx.drawImage(bm, 0, -i * CH);\n    const blob = await new Promise(r => cv.toBlob(r, 'image/jpeg', 0.92));\n    if (!blob) return null;\n    out.push(new File([blob], `part-${i + 1}.jpg`, { type: 'image/jpeg' }));\n  }\n  return out;\n}\n\n// Send a file straight to Cloudflare storage (R2), with progress\nfunction uploadFile(file, type, onProgress) {\n  return new Promise((resolve, reject) => {\n    if (file.size > MAX_MB * 1048576) return reject(new Error(`File is too large (max ${MAX_MB} MB).`));\n    const x = new XMLHttpRequest();\n    x.open('PUT', `/api/admin/upload?type=${type}&name=${encodeURIComponent(file.name)}`);\n    x.setRequestHeader('Authorization', 'Bearer ' + Auth.token);\n    x.setRequestHeader('Content-Type', file.type || (type === 'pdf' ? 'application/pdf' : 'image/jpeg'));\n    if (onProgress) x.upload.onprogress = ev => { if (ev.lengthComputable) onProgress(ev.loaded / ev.total * 100); };\n    x.onload = () => {\n      let r = {}; try { r = JSON.parse(x.responseText); } catch (e) {}\n      x.status >= 200 && x.status < 300 ? resolve(r) : reject(new Error(r.error || 'Upload failed.'));\n    };\n    x.onerror = () => reject(new Error('Upload failed. Check your connection.'));\n    x.send(file);\n  });\n}\nconst $ = s => document.querySelector(s);\n\n(async () => {\n  const u = await boot();\n  if (!u) return location.href = '/login?next=/admin';\n  if (u.role !== 'admin') { $('#main').innerHTML = '<div class=\"empty\" style=\"margin:5rem 0\">Admins only.<br><br><a class=\"btn\" href=\"/\">Home</a></div>'; return; }\n\n  $('#main').innerHTML = `\n    <div class=\"sec-head\"><div><h1 class=\"display\" style=\"font-size:2.8rem\">Admin Dashboard</h1><p class=\"muted\">Upload comics, manage chapters and see your subscribers.</p></div>\n      <a href=\"/\" class=\"btn ghost sm\">View site →</a></div>\n    <div class=\"tabs\">\n      <button data-tab=\"overview\" class=\"active\">📊 Overview</button>\n      <button data-tab=\"upload\">⬆️ Upload Chapter</button>\n      <button data-tab=\"comics\">📚 Comics</button>\n      <button data-tab=\"chapters\">📄 Chapters</button>\n      <button data-tab=\"readers\">👥 Subscribers</button>\n      <button data-tab=\"payments\">💰 Payments</button>\n    </div>\n    <div id=\"tab\"></div>`;\n  document.querySelectorAll('.tabs button').forEach(b => b.onclick = () => show(b.dataset.tab));\n  show(location.hash.slice(1) || 'overview');\n})();\n\nasync function show(tab) {\n  document.querySelectorAll('.tabs button').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));\n  history.replaceState(null, '', '#' + tab);\n  $('#tab').innerHTML = '<div class=\"spinner\"></div>';\n  comics = await api('/api/comics');\n  try { await TABS[tab](); } catch (e) { $('#tab').innerHTML = `<div class=\"error\">${esc(e.message)}</div>`; }\n}\n\nconst TABS = {\n  async overview() {\n    const s = await api('/api/admin/stats');\n    const rev = Object.entries(s.revenue).map(([c, a]) => money(a, c)).join(' + ') || '$0';\n    $('#tab').innerHTML = `\n      ${s.mode === 'demo' ? `<div class=\"notice\" style=\"margin-bottom:1.5rem\">⚠️ <b>Payments are in demo mode.</b> Readers can test subscribing, but no real money is collected yet. Revenue below is test money only.</div>` : ''}\n      <div class=\"stats\">\n        <div class=\"stat\"><div class=\"n\">${s.comics}</div><div class=\"l\">Comics</div></div>\n        <div class=\"stat\"><div class=\"n\">${s.chapters}</div><div class=\"l\">Chapters</div></div>\n        <div class=\"stat\"><div class=\"n\">${s.readers}</div><div class=\"l\">Registered readers</div></div>\n        <div class=\"stat\"><div class=\"n\" style=\"color:var(--green)\">${s.activeSubscribers}</div><div class=\"l\">Active subscribers</div></div>\n        <div class=\"stat\"><div class=\"n\" style=\"color:var(--yellow);font-size:1.5rem;padding:.3rem 0\">${rev}</div><div class=\"l\">Revenue (${s.payments} payments)</div></div>\n      </div>\n      <div class=\"panel\" style=\"display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap\">\n        <div><h3>Ready to post a new chapter?</h3><p class=\"muted\">New chapters automatically appear first in the homepage banner and pop-up.</p></div>\n        <button class=\"btn yellow\" onclick=\"show('upload')\">⬆️ Upload Chapter</button>\n      </div>`;\n  },\n\n  async upload() {\n    if (!comics.length) {\n      $('#tab').innerHTML = `<div class=\"empty\">First create a comic series, then you can upload its chapters.<br><br><button class=\"btn\" onclick=\"show('comics')\">+ Create a Comic</button></div>`;\n      return;\n    }\n    $('#tab').innerHTML = `<div class=\"panel\" style=\"max-width:760px\">\n      <h2 style=\"margin-bottom:1.2rem\">Upload a new chapter (PDF)</h2>\n      <div id=\"upMsg\"></div>\n      <form id=\"upForm\">\n        <div class=\"row\">\n          <div class=\"field\"><label>Comic series</label><select name=\"comicId\" required>${comics.map(c => `<option value=\"${c.id}\">${esc(c.title)}</option>`).join('')}</select></div>\n          <div class=\"field\"><label>Chapter number</label><input type=\"number\" name=\"number\" min=\"1\" step=\"any\" placeholder=\"Auto\"></div>\n        </div>\n        <div class=\"field\"><label>Chapter title</label><input type=\"text\" name=\"title\" placeholder=\"e.g. The Awakening\"></div>\n        <div class=\"field\"><label>Short teaser (shown in the advert banner)</label><textarea name=\"blurb\" rows=\"2\" placeholder=\"One or two exciting sentences about this chapter\"></textarea></div>\n        <div class=\"field\"><label>Chapter file * — one PDF <b>or</b> all the chapter's pictures (select them all; you can fix the order in the next step)</label><input type=\"file\" name=\"pdf\" accept=\"application/pdf,.pdf,image/*\" multiple required></div>\n        <div id=\"thumbs\" class=\"thumbs\"></div>\n        <div class=\"field\" id=\"styleField\"><label>Reading style (for pictures)</label><select name=\"readStyle\">\n          <option value=\"pages\">📖 Pages — one page at a time, swipe left (normal comics)</option>\n          <option value=\"webtoon\">📜 Webtoon — one long vertical scroll</option>\n        </select><small class=\"muted\" style=\"display:block;margin-top:.3rem;font-size:.78rem\">Tip: webtoon is for tall phone-screen images. Regular comic pages should stay on \"Pages\".</small></div>\n        <div class=\"field\"><label>Banner image (optional, wide image for the homepage advert. The comic cover is used if empty)</label><input type=\"file\" name=\"banner\" accept=\"image/*\"></div>\n        <label class=\"check\"><input type=\"checkbox\" name=\"featured\" checked> 📣 Advertise as a new chapter (homepage banner + pop-up)</label>\n        <label class=\"check\"><input type=\"checkbox\" name=\"isFree\"> 🆓 Free chapter (anyone can read without subscribing)</label>\n        <div id=\"bar\" class=\"hidden\" style=\"height:10px;background:var(--line);border-radius:6px;overflow:hidden;margin:1rem 0\"><div id=\"barIn\" style=\"height:100%;width:0;background:var(--yellow);transition:width .2s\"></div></div>\n        <button class=\"btn yellow\" id=\"upBtn\" style=\"margin-top:.6rem\">⬆️ Upload Chapter</button>\n      </form></div>`;\n    const f = $('#upForm');\n    const suggest = () => { const c = comics.find(x => x.id === f.comicId.value); f.number.placeholder = c ? `Auto (${c.chapterCount + 1})` : 'Auto'; };\n    f.comicId.onchange = suggest; suggest();\n\n    // ── Picture picker: numbered thumbnails, reorder & remove before upload ──\n    let pageFiles = [];\n    const thumbsEl = () => $('#thumbs');\n    const renderThumbs = () => {\n      const wrap = thumbsEl(); if (!wrap) return;\n      wrap.innerHTML = ''; \n      if (!pageFiles.length) return;\n      if (!styleTouched && pageFiles[0] && pageFiles[0].type.startsWith('image/')) {\n        const probe = new Image();\n        probe.onload = () => {\n          if (styleTouched) return;\n          const wt = probe.naturalHeight / probe.naturalWidth >= 1.7;\n          f.readStyle.value = wt ? 'webtoon' : 'pages';\n          if (pageFiles.length === 1 && wt) { wrap.dataset.wt = '1'; renderThumbs(); }\n        };\n        probe.src = URL.createObjectURL(pageFiles[0]);\n      }\n      const pdf = pageFiles.find(x => x.type === 'application/pdf' || /\\.pdf$/i.test(x.name));\n      if (pdf) { wrap.innerHTML = `<div class=\"thumb-note\">📄 ${esc(pdf.name)} (${(pdf.size/1048576).toFixed(1)} MB)</div>`; return; }\n      const head = document.createElement('div'); head.className = 'thumb-note';\n      head.innerHTML = wrap.dataset.wt\n          ? `📜 <b>One long picture.</b> It will be read top-to-bottom like a webtoon and split into parts automatically for smooth scrolling.`\n          : `<b>${pageFiles.length} pictures.</b> Reading order: page 1 first, read one page at a time like a book. Use ◀ ▶ to fix the order, ✕ to remove.`;\n      wrap.appendChild(head);\n      const list = document.createElement('div'); list.className = 'thumb-list';\n      pageFiles.forEach((file, i) => {\n        const d = document.createElement('div'); d.className = 'thumb';\n        const img = document.createElement('img'); img.src = URL.createObjectURL(file); img.alt = '';\n        const num = document.createElement('span'); num.className = 'tnum'; num.textContent = i + 1;\n        const controls = document.createElement('div'); controls.className = 'tctl';\n        const mk = (label, fn, dis) => { const b = document.createElement('button'); b.type = 'button'; b.textContent = label; b.onclick = fn; b.disabled = !!dis; return b; };\n        controls.append(\n          mk('◀', () => { [pageFiles[i-1], pageFiles[i]] = [pageFiles[i], pageFiles[i-1]]; renderThumbs(); }, i === 0),\n          mk('✕', () => { pageFiles.splice(i, 1); renderThumbs(); }),\n          mk('▶', () => { [pageFiles[i+1], pageFiles[i]] = [pageFiles[i], pageFiles[i+1]]; renderThumbs(); }, i === pageFiles.length - 1));\n        d.append(img, num, controls);\n        list.appendChild(d);\n      });\n      wrap.appendChild(list);\n    };\n    let styleTouched = false;\n    f.readStyle.onchange = () => { styleTouched = true; };\n    f.pdf.onchange = () => { pageFiles = [...f.pdf.files]; renderThumbs(); };\n    f.onsubmit = async e => {\n      e.preventDefault();\n      const banner = f.banner.files[0];\n      let files = pageFiles.slice();\n      if (!files.length) { $('#upMsg').innerHTML = '<div class=\"error\">Please choose a PDF or some pictures first.</div>'; return; }\n      const hasPdf = files.find(x => x.type === 'application/pdf' || /\\.pdf$/i.test(x.name));\n      if (hasPdf && files.length > 1) { $('#upMsg').innerHTML = '<div class=\"error\">Choose either ONE PDF, or pictures only — not both.</div>'; return; }\n      if (!hasPdf && !files.every(x => x.type.startsWith('image/'))) { $('#upMsg').innerHTML = '<div class=\"error\">Chapters can be one PDF file, or pictures (JPG/PNG/WebP).</div>'; return; }\n      if (files.length > 500) { $('#upMsg').innerHTML = '<div class=\"error\">Max 500 pictures per chapter — split it into two chapters.</div>'; return; }\n      const btn = $('#upBtn'); btn.disabled = true;\n      $('#upMsg').innerHTML = ''; $('#bar').classList.remove('hidden');\n      try {\n        let body;\n        if (hasPdf) {\n          if (hasPdf.size > MAX_MB * 1048576) throw new Error(`This PDF is ${(hasPdf.size / 1048576).toFixed(0)} MB. The maximum is ${MAX_MB} MB.`);\n          btn.textContent = 'Uploading PDF...';\n          const up = await uploadFile(hasPdf, 'pdf', pct => $('#barIn').style.width = pct + '%');\n          body = { comicId: f.comicId.value, number: f.number.value, title: f.title.value, blurb: f.blurb.value,\n            pdf: up.key, size: hasPdf.size, originalName: hasPdf.name, isFree: f.isFree.checked, featured: f.featured.checked };\n        } else {\n          if (files.length === 1) {\n            btn.textContent = 'Checking picture...';\n            const slices = await sliceLongStrip(files[0]).catch(() => null);\n            if (slices && slices.length > 1) { files = slices; f.readStyle.value = 'webtoon'; }\n          }\n          btn.textContent = `Uploading pictures (0/${files.length})...`;\n          const keys = [];\n          for (let i = 0; i < files.length; i++) {\n            const up = await uploadFile(files[i], 'page', pct => {\n              $('#barIn').style.width = ((i + pct / 100) / files.length * 100) + '%';\n              btn.textContent = `Uploading pictures (${i + (pct > 99 ? 1 : 0)}/${files.length})...`;\n            });\n            keys.push(up.key);\n          }\n          btn.textContent = 'Saving...';\n          body = { comicId: f.comicId.value, number: f.number.value, title: f.title.value, blurb: f.blurb.value,\n            pages: keys, style: f.readStyle.value, size: files.reduce((a, x) => a + x.size, 0), originalName: `${files.length} pictures`, isFree: f.isFree.checked, featured: f.featured.checked };\n        }\n        if (banner) { btn.textContent = 'Uploading banner...'; body.banner = (await uploadFile(banner, 'banner')).key; }\n        btn.textContent = 'Saving...';\n        const r = await api('/api/admin/chapters', { body });\n        $('#upMsg').innerHTML = `<div class=\"success\">✅ Uploaded <b>${esc(r.comicTitle)}, Chapter ${r.number}: ${esc(r.title)}</b> (${r.type === 'images' ? r.pageCount + ' pictures · ' + (r.style === 'webtoon' ? 'webtoon' : 'pages') : 'PDF'}). <a href=\"/read?id=${r.id}\" style=\"text-decoration:underline\">Preview it</a></div>`;\n        f.reset(); pageFiles = []; renderThumbs(); $('#bar').classList.add('hidden'); $('#barIn').style.width = 0;\n        comics = await api('/api/comics'); suggest();\n      } catch (err) { $('#upMsg').innerHTML = `<div class=\"error\">${esc(err.message)}</div>`; }\n      btn.disabled = false; btn.textContent = '⬆️ Upload Chapter';\n    };\n  },\n\n  async comics() {\n    $('#tab').innerHTML = `\n      <div class=\"panel\" style=\"max-width:760px;margin-bottom:2rem\">\n        <h2 style=\"margin-bottom:1.2rem\">+ Create a new comic series</h2>\n        <div id=\"cMsg\"></div>\n        <form id=\"cForm\">\n          <div class=\"row\">\n            <div class=\"field\"><label>Title *</label><input type=\"text\" name=\"title\" required></div>\n            <div class=\"field\"><label>Genre</label><input type=\"text\" name=\"genre\" placeholder=\"Action, Romance, Fantasy...\"></div>\n          </div>\n          <div class=\"field\"><label>Description</label><textarea name=\"description\" rows=\"3\"></textarea></div>\n          <div class=\"field\"><label>Cover image (portrait works best)</label><input type=\"file\" name=\"cover\" accept=\"image/*\"></div>\n          <button class=\"btn\">Create Comic</button>\n        </form>\n      </div>\n      <div class=\"grid\">${comics.map(c => `\n        <div class=\"comic\">\n          <a href=\"/comic?id=${c.id}\">${coverDiv('cover', c.cover, c.title)}</a>\n          <div class=\"info\"><h3>${esc(c.title)}</h3><div class=\"sm\">${c.chapterCount} chapters</div>\n            <div style=\"display:flex;gap:.4rem;margin-top:.7rem;flex-wrap:wrap\">\n              <button class=\"btn ghost sm\" onclick=\"editComic('${c.id}')\">Edit</button>\n              <button class=\"btn danger sm\" onclick=\"delComic('${c.id}')\">Delete</button>\n            </div></div>\n        </div>`).join('') || '<div class=\"empty\" style=\"grid-column:1/-1\">No comics yet.</div>'}</div>`;\n    $('#cForm').onsubmit = async e => {\n      e.preventDefault();\n      const f = e.target, btn = f.querySelector('button'); btn.disabled = true;\n      try {\n        const cover = f.cover.files[0] ? (await uploadFile(f.cover.files[0], 'cover')).key : null;\n        await api('/api/admin/comics', { body: { title: f.title.value, genre: f.genre.value, description: f.description.value, cover } });\n        toast('Comic created!'); show('comics');\n      }\n      catch (err) { $('#cMsg').innerHTML = `<div class=\"error\">${esc(err.message)}</div>`; btn.disabled = false; }\n    };\n  },\n\n  async chapters() {\n    const list = await api('/api/admin/chapters');\n    $('#tab').innerHTML = list.length ? `<div class=\"table-wrap\"><table>\n      <tr><th>Comic</th><th>#</th><th>Title</th><th>Uploaded</th><th>Free</th><th>Advertise</th><th></th></tr>\n      ${list.map(ch => `<tr>\n        <td><b>${esc(ch.comicTitle)}</b></td><td>${ch.number}</td><td>${esc(ch.title)}</td>\n        <td class=\"muted\">${fmtDate(ch.createdAt)}<br><span style=\"font-size:.78rem\">${ch.type === 'images' ? ch.pageCount + ' pics ⇄' : 'PDF'} · ${ch.size ? (ch.size / 1048576).toFixed(1) + ' MB' : ''}</span></td>\n        <td><label class=\"check\" style=\"margin:0\"><input type=\"checkbox\" ${ch.isFree ? 'checked' : ''} onchange=\"patchCh('${ch.id}',{isFree:this.checked})\"></label></td>\n        <td><label class=\"check\" style=\"margin:0\"><input type=\"checkbox\" ${ch.featured ? 'checked' : ''} onchange=\"patchCh('${ch.id}',{featured:this.checked})\"></label></td>\n        <td style=\"white-space:nowrap\"><a class=\"btn ghost sm\" href=\"/read?id=${ch.id}\">Read</a> <button class=\"btn danger sm\" onclick=\"delCh('${ch.id}')\">Delete</button></td>\n      </tr>`).join('')}</table></div>` : `<div class=\"empty\">No chapters yet. <br><br><button class=\"btn\" onclick=\"show('upload')\">Upload one</button></div>`;\n  },\n\n  async readers() {\n    const users = await api('/api/admin/users');\n    $('#tab').innerHTML = `\n      <p class=\"notice\" style=\"margin-bottom:1.2rem\">💡 If someone pays you directly (for example by MoMo transfer), click <b>+30 days</b> or <b>+1 year</b> to give them access by hand.</p>\n      ${users.length ? `<div class=\"table-wrap\"><table>\n      <tr><th>Reader</th><th>Joined</th><th>Status</th><th>Expires</th><th>Give access</th></tr>\n      ${users.map(r => `<tr>\n        <td><b>${esc(r.name)}</b><br><span class=\"muted\">${esc(r.email)}</span></td>\n        <td class=\"muted\">${fmtDate(r.createdAt)}</td>\n        <td><span class=\"status ${r.subscribed ? 'active' : 'none'}\">${r.subscribed ? 'Active' : 'None'}</span><br><span class=\"muted\" style=\"font-size:.8rem\">${r.subscription ? esc(r.subscription.planName) : ''}</span></td>\n        <td>${r.subscription ? fmtDate(r.subscription.expiresAt) : '-'}</td>\n        <td style=\"white-space:nowrap\"><button class=\"btn ghost sm\" onclick=\"grant('${r.id}',30)\">+30 days</button> <button class=\"btn ghost sm\" onclick=\"grant('${r.id}',365)\">+1 year</button>\n          ${r.subscribed ? `<button class=\"btn danger sm\" onclick=\"revoke('${r.id}')\">Remove</button>` : ''}</td>\n      </tr>`).join('')}</table></div>` : '<div class=\"empty\">No readers have signed up yet.</div>'}`;\n  },\n\n  async payments() {\n    const pays = await api('/api/admin/payments');\n    $('#tab').innerHTML = pays.length ? `<div class=\"table-wrap\"><table>\n      <tr><th>Date</th><th>Reader</th><th>Plan</th><th>Method</th><th>Amount</th><th>Ref</th><th>Status</th></tr>\n      ${pays.map(p => `<tr><td class=\"muted\">${fmtDate(p.createdAt)}</td><td>${esc(p.userEmail)}</td><td>${esc(p.planName)}</td>\n        <td>${esc(p.methodName)}${p.phone ? `<br><span class=\"muted\" style=\"font-size:.8rem\">${esc(p.phone)}</span>` : ''}</td>\n        <td><b>${money(p.amount, p.currency)}</b>${p.mode === 'demo' ? '<br><span class=\"muted\" style=\"font-size:.75rem\">demo</span>' : ''}</td>\n        <td class=\"muted\" style=\"font-size:.8rem\">${esc(p.reference)}</td><td><span class=\"status ${p.status}\">${p.status}</span></td></tr>`).join('')}\n      </table></div>` : '<div class=\"empty\">No payments yet.</div>';\n  },\n};\n\nasync function patchCh(id, body) { try { await api('/api/admin/chapters/' + id, { method: 'PATCH', body }); toast('Saved'); } catch (e) { toast(e.message, true); } }\nasync function delCh(id) { if (!confirm('Delete this chapter and its PDF? This cannot be undone.')) return; await api('/api/admin/chapters/' + id, { method: 'DELETE' }); toast('Chapter deleted'); show('chapters'); }\nasync function delComic(id) { const c = comics.find(x => x.id === id); if (!confirm(`Delete \"${c.title}\" and ALL its chapters? This cannot be undone.`)) return; await api('/api/admin/comics/' + id, { method: 'DELETE' }); toast('Comic deleted'); show('comics'); }\nasync function grant(id, days) { await api(`/api/admin/users/${id}/grant`, { body: { days } }); toast(`Access added: ${days} days`); show('readers'); }\nasync function revoke(id) { if (!confirm('Remove this reader\\'s subscription?')) return; await api(`/api/admin/users/${id}/revoke`, { method: 'POST' }); toast('Subscription removed'); show('readers'); }\n\nfunction editComic(id) {\n  const c = comics.find(x => x.id === id);\n  const m = document.createElement('div'); m.className = 'modal';\n  m.innerHTML = `<div class=\"box\"><button class=\"x\">✕</button><div class=\"body\">\n    <h2 style=\"margin-bottom:1rem\">Edit comic</h2><div id=\"eMsg\"></div>\n    <form id=\"eForm\">\n      <div class=\"field\"><label>Title</label><input type=\"text\" name=\"title\" value=\"${esc(c.title)}\" required></div>\n      <div class=\"field\"><label>Genre</label><input type=\"text\" name=\"genre\" value=\"${esc(c.genre)}\"></div>\n      <div class=\"field\"><label>Description</label><textarea name=\"description\" rows=\"4\">${esc(c.description)}</textarea></div>\n      <div class=\"field\"><label>New cover image (optional)</label><input type=\"file\" name=\"cover\" accept=\"image/*\"></div>\n      <button class=\"btn block\">Save changes</button></form></div></div>`;\n  document.body.appendChild(m);\n  m.onclick = e => { if (e.target === m || e.target.classList.contains('x')) m.remove(); };\n  m.querySelector('form').onsubmit = async e => {\n    e.preventDefault();\n    const f = e.target;\n    try {\n      const cover = f.cover.files[0] ? (await uploadFile(f.cover.files[0], 'cover')).key : undefined;\n      await api('/api/admin/comics/' + id, { method: 'PUT', body: { title: f.title.value, genre: f.genre.value, description: f.description.value, cover } });\n      m.remove(); toast('Saved'); show('comics');\n    }\n    catch (err) { m.querySelector('#eMsg').innerHTML = `<div class=\"error\">${esc(err.message)}</div>`; }\n  };\n}\n</script>\n</body>\n</html>\n"}, "/app.js": {"type": "application/javascript; charset=utf-8", "body": "// Shared code for every Morgan.stdio page\nconst LOGO_SVG = `<svg viewBox=\"0 0 64 64\" aria-label=\"Morgan.stdio logo\">\n  <defs><linearGradient id=\"mg\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ff3d5a\"/><stop offset=\"1\" stop-color=\"#ffd23f\"/></linearGradient></defs>\n  <rect x=\"5\" y=\"5\" width=\"56\" height=\"56\" rx=\"14\" fill=\"#000\"/>\n  <rect x=\"2\" y=\"2\" width=\"56\" height=\"56\" rx=\"14\" fill=\"url(#mg)\"/>\n  <path d=\"M13 46V14h8l9 15 9-15h8v32h-8V28l-9 14-9-14v18z\" fill=\"#000\" transform=\"translate(2 2)\"/>\n  <path d=\"M13 46V14h8l9 15 9-15h8v32h-8V28l-9 14-9-14v18z\" fill=\"#fff\"/>\n</svg>`;\n\nconst Auth = {\n  get token() { return localStorage.getItem('ms_token'); },\n  set token(v) { v ? localStorage.setItem('ms_token', v) : localStorage.removeItem('ms_token'); },\n  user: null,\n};\n\nasync function api(path, opts = {}) {\n  const headers = opts.headers || {};\n  if (Auth.token) headers.Authorization = 'Bearer ' + Auth.token;\n  let body = opts.body;\n  if (body && !(body instanceof FormData)) { headers['Content-Type'] = 'application/json'; body = JSON.stringify(body); }\n  let res;\n  try { res = await fetch(path, { method: opts.method || (body ? 'POST' : 'GET'), headers, body }); }\n  catch (e) { throw new Error('Cannot reach the server. Check your internet connection and try again.'); }\n  let data = null;\n  try { data = await res.json(); } catch (e) {}\n  if (!res.ok) {\n    if (!data && res.status >= 500) throw new Error('The website server is offline right now. Please try again in a moment.');\n    throw new Error((data && data.error) || 'Something went wrong. Please try again.');\n  }\n  return data;\n}\n\nasync function loadUser() {\n  if (!Auth.token) return (Auth.user = null);\n  try { const r = await api('/api/me'); Auth.user = r.user; if (!r.user) Auth.token = null; }\n  catch (e) { Auth.user = null; }\n  return Auth.user;\n}\n\nasync function logout() {\n  try { await api('/api/logout', { method: 'POST' }); } catch (e) {}\n  Auth.token = null; Auth.user = null; location.href = '/';\n}\n\nfunction esc(s) { return String(s ?? '').replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c])); }\nfunction fmtDate(d) { return new Date(d).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }); }\nfunction ago(d) {\n  const s = (Date.now() - new Date(d)) / 1000;\n  if (s < 3600) return Math.max(1, Math.round(s / 60)) + ' min ago';\n  if (s < 86400) return Math.round(s / 3600) + 'h ago';\n  if (s < 86400 * 7) return Math.round(s / 86400) + 'd ago';\n  return fmtDate(d);\n}\nconst isNew = d => Date.now() - new Date(d) < 7 * 86400000;\nfunction money(amount, cur) { return cur === 'XAF' ? `${Number(amount).toLocaleString()} CFA` : `$${amount}`; }\nfunction qs(k) { return new URLSearchParams(location.search).get(k); }\n\n// Colorful generated cover when no image was uploaded\nfunction genCoverStyle(title) {\n  let h = 0; for (const c of String(title)) h = (h * 31 + c.charCodeAt(0)) % 360;\n  return `background: radial-gradient(rgba(255,255,255,.12) 1.2px, transparent 1.3px) 0 0/12px 12px, linear-gradient(135deg, hsl(${h} 85% 55%), hsl(${(h + 60) % 360} 80% 35%));`;\n}\nfunction coverDiv(cls, url, title) {\n  return url\n    ? `<div class=\"${cls}\" style=\"background-image:url('${esc(url)}')\"></div>`\n    : `<div class=\"${cls} gen-cover\" style=\"${genCoverStyle(title)}\">${esc(title)}</div>`;\n}\n\nfunction toast(msg, err) {\n  let t = document.getElementById('toast');\n  if (!t) { t = document.createElement('div'); t.id = 'toast'; document.body.appendChild(t); }\n  t.textContent = msg; t.className = err ? 'err show' : 'show';\n  clearTimeout(t._h); t._h = setTimeout(() => t.className = t.className.replace('show', ''), 3200);\n}\n\nfunction renderNav() {\n  const u = Auth.user;\n  const el = document.getElementById('nav');\n  if (!el) return;\n  el.className = 'nav';\n  el.innerHTML = `<div class=\"wrap\">\n    <a href=\"/\" class=\"brand\">${LOGO_SVG}<span class=\"txt\">Morgan<b>.stdio</b></span></a>\n    <div class=\"nav-links\">\n      <a href=\"/#comics\" class=\"hide-sm\">Comics</a>\n      ${u && u.role === 'admin' ? `<a href=\"/admin\">Dashboard <span class=\"pill admin\">Admin</span></a>` : ''}\n      ${u && u.role !== 'admin' && !u.subscribed ? `<a href=\"/subscribe\" class=\"btn yellow sm\">Subscribe</a>` : ''}\n      ${!u ? `<a href=\"/subscribe\" class=\"hide-sm\">Pricing</a><a href=\"/login\" class=\"btn sm\">Log in</a>` : ''}\n      ${u ? `<a href=\"/account\" title=\"My account\">${u.subscribed && u.role !== 'admin' ? '<span class=\"pill\">Member</span> ' : ''}👤 <span class=\"hide-sm\">${esc(u.name.split(' ')[0])}</span></a>\n             <a href=\"#\" onclick=\"logout();return false\" class=\"muted hide-sm\">Log out</a>` : ''}\n    </div></div>`;\n}\n\nfunction renderFooter() {\n  const el = document.getElementById('footer');\n  if (!el) return;\n  el.innerHTML = `<div class=\"wrap\">\n    <a href=\"/\" class=\"brand\" style=\"font-size:1rem\">${LOGO_SVG.replace('<svg', '<svg style=\"width:30px;height:30px\"')}<span>Morgan<b>.stdio</b></span></a>\n    <div>© ${new Date().getFullYear()} Morgan.stdio · All comics are the property of their creators.</div>\n    <div><a href=\"/subscribe\">Pricing</a> · <a href=\"/login\">Account</a></div></div>`;\n}\n\nasync function boot() {\n  await loadUser();\n  renderNav();\n  renderFooter();\n  return Auth.user;\n}\n"}, "/comic.html": {"type": "text/html; charset=utf-8", "body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Comic · Morgan.stdio</title>\n<link rel=\"icon\" href=\"/logo.svg\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n<nav id=\"nav\"></nav>\n<main class=\"wrap\" id=\"main\"><div class=\"spinner\" style=\"margin:8rem auto\"></div></main>\n<footer id=\"footer\"></footer>\n<script src=\"/app.js\"></script>\n<script>\n(async () => {\n  const user = await boot();\n  const main = document.getElementById('main');\n  try {\n    const c = await api('/api/comics/' + encodeURIComponent(qs('id')));\n    document.title = c.title + ' · Morgan.stdio';\n    const first = c.chapters[0];\n    const newest = c.chapters[c.chapters.length - 1];\n    const locked = c.chapters.some(ch => ch.locked);\n    main.innerHTML = `\n      <div class=\"detail\">\n        ${coverDiv('cover', c.cover, c.title)}\n        <div>\n          ${c.genre ? `<span class=\"mini lock\" style=\"margin:0 0 .8rem;display:inline-block\">${esc(c.genre)}</span>` : ''}\n          <h1 class=\"display\">${esc(c.title)}</h1>\n          <p class=\"muted\" style=\"margin:.4rem 0 1rem\">${c.chapters.length} chapter${c.chapters.length === 1 ? '' : 's'} · Updated ${ago(c.latestAt)}</p>\n          <p style=\"max-width:680px;margin-bottom:1.5rem;white-space:pre-line\">${esc(c.description) || '<span class=\"muted\">No description yet.</span>'}</p>\n          <div style=\"display:flex;gap:.8rem;flex-wrap:wrap\">\n            ${first ? `<a class=\"btn\" href=\"/read?id=${first.id}\">▶ Start Reading</a>` : ''}\n            ${newest && newest !== first ? `<a class=\"btn ghost\" href=\"/read?id=${newest.id}\">Latest: Ch. ${newest.number}</a>` : ''}\n          </div>\n          ${locked && !user ? `<p class=\"notice\" style=\"margin-top:1.3rem\">🔒 Some chapters are for members only. <a href=\"/login?next=${encodeURIComponent(location.pathname + location.search)}\" style=\"text-decoration:underline\">Log in</a> or <a href=\"/subscribe\" style=\"text-decoration:underline\">subscribe</a> to read everything.</p>` : ''}\n          ${locked && user && !user.subscribed ? `<p class=\"notice\" style=\"margin-top:1.3rem\">🔒 Some chapters are for members only. <a href=\"/subscribe\" style=\"text-decoration:underline\">Subscribe from $2/month or 500 CFA</a> to unlock them.</p>` : ''}\n        </div>\n      </div>\n      <div class=\"sec-head\"><h2 class=\"display\">Chapters</h2></div>\n      <div class=\"chapters\">${c.chapters.length ? c.chapters.slice().reverse().map(ch => `\n        <a class=\"chapter\" href=\"/read?id=${ch.id}\">\n          <div class=\"num\">#${ch.number}</div>\n          <div class=\"t\"><h4>${esc(ch.title)}${isNew(ch.createdAt) ? '<span class=\"mini new\">New</span>' : ''}${ch.isFree ? '<span class=\"mini free\">Free</span>' : ''}</h4>\n            ${ch.type === 'images' ? '<span class=\"muted\" style=\"font-size:.78rem\">' + (ch.style === 'webtoon' ? '📜 Webtoon' : '📖 ' + ch.pageCount + ' pages') + '</span>' : ''}\n            <div class=\"sm\">${fmtDate(ch.createdAt)}</div></div>\n          <span class=\"${ch.locked ? 'mini lock' : 'btn sm'}\">${ch.locked ? '🔒 Members' : 'Read'}</span>\n        </a>`).join('') : '<div class=\"empty\">No chapters uploaded yet.</div>'}\n      </div><div style=\"height:2rem\"></div>`;\n  } catch (e) {\n    main.innerHTML = `<div class=\"empty\" style=\"margin:5rem 0\">${esc(e.message)} <br><br><a class=\"btn\" href=\"/\">Back home</a></div>`;\n  }\n})();\n</script>\n</body>\n</html>\n"}, "/index.html": {"type": "text/html; charset=utf-8", "body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Morgan.stdio · Read Comics Online</title>\n<link rel=\"icon\" href=\"/logo.svg\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n<nav id=\"nav\"></nav>\n<main>\n  <!-- NEW CHAPTER ADVERT BANNER -->\n  <section class=\"hero\" id=\"hero\"><div class=\"spinner\" style=\"margin:12rem auto\"></div></section>\n\n  <section class=\"block\" id=\"latestSec\">\n    <div class=\"wrap\">\n      <div class=\"sec-head\"><h2 class=\"display\">🔥 Latest <span>Releases</span></h2><span class=\"muted\">Newest chapters first</span></div>\n      <div class=\"strip\" id=\"latest\"></div>\n    </div>\n  </section>\n\n  <section class=\"block halftone\" id=\"comics\">\n    <div class=\"wrap\">\n      <div class=\"sec-head\"><h2 class=\"display\">All <span>Comics</span></h2><span class=\"muted\" id=\"comicCount\"></span></div>\n      <div class=\"grid\" id=\"grid\"></div>\n    </div>\n  </section>\n\n  <section class=\"block\" id=\"joinSec\">\n    <div class=\"wrap\">\n      <div class=\"panel\" style=\"display:flex;align-items:center;justify-content:space-between;gap:1.5rem;flex-wrap:wrap;background:linear-gradient(120deg,#2a1020,#1b1b2e 55%,#10283a);\">\n        <div>\n          <h2 class=\"display\" style=\"font-size:2.3rem\">Unlock every chapter</h2>\n          <p class=\"muted\">Only <b style=\"color:#fff\">$2/month</b>, <b style=\"color:#fff\">$12/year</b>, or <b style=\"color:#fff\">500 CFA/month</b> with MTN MoMo or Orange Money.</p>\n        </div>\n        <a href=\"/subscribe\" class=\"btn yellow\">See Plans →</a>\n      </div>\n    </div>\n  </section>\n</main>\n<footer id=\"footer\"></footer>\n\n<script src=\"/app.js\"></script>\n<script>\n(async () => {\n  const user = await boot();\n  if (user && user.subscribed) document.getElementById('joinSec').classList.add('hidden');\n\n  const [featured, latest, comics] = await Promise.all([api('/api/featured'), api('/api/latest'), api('/api/comics')]);\n\n  // ── Hero advert carousel (newest featured chapters first) ──\n  const hero = document.getElementById('hero');\n  if (!featured.length) {\n    hero.innerHTML = `<div class=\"hero-empty halftone\"><div class=\"wrap\">\n      <div style=\"width:110px;margin:0 auto 1rem\">${LOGO_SVG}</div>\n      <h1 class=\"display\">Morgan.stdio</h1>\n      <p class=\"muted\" style=\"font-size:1.15rem;margin:.6rem 0 1.6rem\">Original comics. New chapters every week.</p>\n      <a href=\"#comics\" class=\"btn yellow\">Browse Comics</a></div></div>`;\n  } else {\n    hero.innerHTML = `<div class=\"slides\">${featured.map((ch, i) => `\n      <div class=\"slide ${i === 0 ? 'active' : ''}\">\n        <div class=\"bg\" style=\"${ch.banner ? `background-image:url('${esc(ch.banner)}')` : genCoverStyle(ch.comicTitle)}\"></div>\n        <div class=\"wrap\"><div class=\"content\">\n          <span class=\"badge-new\"><span class=\"dot\"></span> ${i === 0 ? 'New Chapter Out Now' : 'New Chapter'}</span>\n          <h1 class=\"display\">${esc(ch.comicTitle)}</h1>\n          <h2>Chapter ${ch.number}: ${esc(ch.title)} ${ch.isFree ? '<span class=\"mini free\">Free</span>' : ''}</h2>\n          <p>${esc(ch.blurb)}</p>\n          <div class=\"actions\">\n            <a href=\"/read?id=${ch.id}\" class=\"btn\">▶ Read Now</a>\n            <a href=\"/comic?id=${ch.comicId}\" class=\"btn ghost\">All Chapters</a>\n          </div>\n        </div></div>\n      </div>`).join('')}</div>\n      ${featured.length > 1 ? `<div class=\"dots\"><div class=\"wrap\">${featured.map((_, i) => `<button class=\"${i === 0 ? 'active' : ''}\" data-i=\"${i}\" aria-label=\"Slide ${i + 1}\"></button>`).join('')}</div></div>` : ''}`;\n    const slides = hero.querySelectorAll('.slide'), dots = hero.querySelectorAll('.dots button');\n    let cur = 0, timer;\n    const go = i => { slides[cur].classList.remove('active'); dots[cur] && dots[cur].classList.remove('active'); cur = (i + slides.length) % slides.length; slides[cur].classList.add('active'); dots[cur] && dots[cur].classList.add('active'); };\n    const auto = () => { clearInterval(timer); if (slides.length > 1) timer = setInterval(() => go(cur + 1), 6000); };\n    dots.forEach(d => d.onclick = () => { go(+d.dataset.i); auto(); });\n    auto();\n\n    // ── Pop-up advert for the newest chapter (shown once per chapter) ──\n    const top = featured[0];\n    if (isNew(top.createdAt) && localStorage.getItem('ms_seen_popup') !== top.id) {\n      setTimeout(() => {\n        const m = document.createElement('div');\n        m.className = 'modal';\n        m.innerHTML = `<div class=\"box\">\n          <button class=\"x\" aria-label=\"Close\">✕</button>\n          <div class=\"art\" style=\"${top.banner ? `background-image:url('${esc(top.banner)}')` : genCoverStyle(top.comicTitle)}\"><span class=\"badge-new\"><span class=\"dot\"></span> Just Released</span></div>\n          <div class=\"body\">\n            <h2 class=\"display\" style=\"font-size:2.2rem;line-height:1\">${esc(top.comicTitle)}</h2>\n            <p style=\"color:var(--yellow);font-weight:700;margin:.3rem 0 .7rem\">Chapter ${top.number}: ${esc(top.title)}</p>\n            <p class=\"muted\" style=\"margin-bottom:1.3rem\">${esc(top.blurb).slice(0, 180)}</p>\n            <a href=\"/read?id=${top.id}\" class=\"btn block\">▶ Read the New Chapter</a>\n          </div></div>`;\n        const close = () => { localStorage.setItem('ms_seen_popup', top.id); m.remove(); };\n        m.onclick = e => { if (e.target === m || e.target.classList.contains('x')) close(); };\n        m.querySelector('a').onclick = () => localStorage.setItem('ms_seen_popup', top.id);\n        document.body.appendChild(m);\n      }, 1200);\n    }\n  }\n\n  // ── Latest releases strip ──\n  const L = document.getElementById('latest');\n  if (!latest.length) document.getElementById('latestSec').classList.add('hidden');\n  L.innerHTML = latest.map(ch => `\n    <a class=\"chip\" href=\"/read?id=${ch.id}\">\n      ${ch.cover ? `<div class=\"thumb\" style=\"background-image:url('${esc(ch.cover)}')\"></div>` : `<div class=\"thumb\" style=\"${genCoverStyle(ch.comicTitle)}\"></div>`}\n      <div><h4>${esc(ch.comicTitle)}</h4>\n        <div class=\"sm\">Ch. ${ch.number} · ${esc(ch.title)}</div>\n        <div class=\"sm\" style=\"margin-top:.35rem\">${isNew(ch.createdAt) ? '<span class=\"mini new\" style=\"margin:0\">New</span> ' : ''}${ch.isFree ? '<span class=\"mini free\" style=\"margin:0\">Free</span> ' : ch.locked ? '<span class=\"mini lock\" style=\"margin:0\">🔒 Members</span> ' : ''}${ago(ch.createdAt)}</div>\n      </div></a>`).join('');\n\n  // ── Comics grid ──\n  document.getElementById('comicCount').textContent = comics.length ? `${comics.length} series` : '';\n  document.getElementById('grid').innerHTML = comics.length ? comics.map(c => `\n    <a class=\"comic\" href=\"/comic?id=${c.id}\">\n      ${coverDiv('cover', c.cover, c.title)}\n      ${isNew(c.latestAt) && c.chapterCount ? '<span class=\"tag\">New Ch.</span>' : ''}\n      ${c.genre ? `<span class=\"tag genre\">${esc(c.genre)}</span>` : ''}\n      <div class=\"info\"><h3>${esc(c.title)}</h3><div class=\"sm\">${c.chapterCount} chapter${c.chapterCount === 1 ? '' : 's'}</div></div>\n    </a>`).join('') : `<div class=\"empty\" style=\"grid-column:1/-1\">No comics yet. Check back soon!</div>`;\n})();\n</script>\n</body>\n</html>\n"}, "/login.html": {"type": "text/html; charset=utf-8", "body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Log in · Morgan.stdio</title>\n<link rel=\"icon\" href=\"/logo.svg\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body class=\"halftone\">\n<nav id=\"nav\"></nav>\n<main class=\"wrap\" style=\"max-width:460px;padding:3.5rem 0\">\n  <div class=\"panel\">\n    <div style=\"width:64px;margin:0 auto 1rem\" id=\"logo\"></div>\n    <div class=\"tabs\" style=\"justify-content:center\">\n      <button class=\"active\" data-t=\"login\">Log in</button>\n      <button data-t=\"register\">Create account</button>\n    </div>\n    <div id=\"msg\"></div>\n    <form id=\"form\">\n      <div class=\"field hidden\" id=\"nameField\"><label>Your name</label><input type=\"text\" name=\"name\" autocomplete=\"name\"></div>\n      <div class=\"field\"><label>Email</label><input type=\"email\" name=\"email\" required autocomplete=\"email\"></div>\n      <div class=\"field\"><label>Password</label><input type=\"password\" name=\"password\" required minlength=\"6\" autocomplete=\"current-password\"></div>\n      <button class=\"btn block\" id=\"submitBtn\">Log in</button>\n    </form>\n    <p class=\"muted\" style=\"text-align:center;font-size:.85rem;margin-top:1.2rem\" id=\"hint\">New here? Create a free account, then subscribe to unlock every chapter.</p>\n  </div>\n</main>\n<footer id=\"footer\"></footer>\n<script src=\"/app.js\"></script>\n<script>\n(async () => {\n  document.getElementById('logo').innerHTML = LOGO_SVG;\n  const user = await boot();\n  const next = qs('next');\n  const go = u => location.href = next || (u.role === 'admin' ? '/admin' : u.subscribed ? '/' : '/subscribe');\n  if (user) return go(user);\n\n  let mode = qs('mode') === 'register' ? 'register' : 'login';\n  const form = document.getElementById('form'), msg = document.getElementById('msg');\n  const set = m => {\n    mode = m;\n    document.querySelectorAll('.tabs button').forEach(b => b.classList.toggle('active', b.dataset.t === m));\n    document.getElementById('nameField').classList.toggle('hidden', m !== 'register');\n    form.name.required = m === 'register';\n    document.getElementById('submitBtn').textContent = m === 'register' ? 'Create account' : 'Log in';\n    form.password.autocomplete = m === 'register' ? 'new-password' : 'current-password';\n    msg.innerHTML = '';\n  };\n  document.querySelectorAll('.tabs button').forEach(b => b.onclick = () => set(b.dataset.t));\n  set(mode);\n\n  form.onsubmit = async e => {\n    e.preventDefault();\n    const btn = document.getElementById('submitBtn'); btn.disabled = true;\n    try {\n      const body = { email: form.email.value, password: form.password.value };\n      if (mode === 'register') body.name = form.name.value;\n      const r = await api('/api/' + mode, { body });\n      Auth.token = r.token;\n      go(r.user);\n    } catch (err) { msg.innerHTML = `<div class=\"error\">${esc(err.message)}</div>`; btn.disabled = false; }\n  };\n})();\n</script>\n</body>\n</html>\n"}, "/logo.svg": {"type": "image/svg+xml", "body": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\">\n  <defs><linearGradient id=\"mg\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ff3d5a\"/><stop offset=\"1\" stop-color=\"#ffd23f\"/></linearGradient></defs>\n  <rect x=\"5\" y=\"5\" width=\"56\" height=\"56\" rx=\"14\" fill=\"#000\"/>\n  <rect x=\"2\" y=\"2\" width=\"56\" height=\"56\" rx=\"14\" fill=\"url(#mg)\"/>\n  <path d=\"M13 46V14h8l9 15 9-15h8v32h-8V28l-9 14-9-14v18z\" fill=\"#000\" transform=\"translate(2 2)\"/>\n  <path d=\"M13 46V14h8l9 15 9-15h8v32h-8V28l-9 14-9-14v18z\" fill=\"#fff\"/>\n</svg>\n"}, "/read.html": {"type": "text/html; charset=utf-8", "body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Reading · Morgan.stdio</title>\n<link rel=\"icon\" href=\"/logo.svg\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n<div class=\"progress\" id=\"progress\"></div>\n<nav id=\"nav\"></nav>\n<div class=\"reader-bar hidden\" id=\"bar\"><div class=\"wrap\">\n  <div style=\"min-width:0\"><a id=\"backLink\" class=\"muted\" style=\"font-size:.85rem\">← Back</a>\n    <div id=\"chTitle\" style=\"font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis\"></div></div>\n  <div style=\"display:flex;gap:.5rem;align-items:center\"><span class=\"muted hide-sm\" id=\"pageInfo\" style=\"font-size:.85rem\"></span>\n    <a class=\"btn ghost sm\" id=\"prevBtn\">‹ Prev</a><a class=\"btn sm\" id=\"nextBtn\">Next ›</a></div>\n</div></div>\n<main id=\"main\"><div class=\"spinner\" style=\"margin:8rem auto\"></div></main>\n<div class=\"wrap hidden\" id=\"endNav\" style=\"display:flex;justify-content:center;gap:1rem;margin-bottom:3rem\"></div>\n<footer id=\"footer\"></footer>\n\n<script src=\"/app.js\"></script>\n<script>\nconst loadPdfJs = () => new Promise(res => { const t = document.createElement(\"script\"); t.src = \"https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js\"; t.onload = res; document.head.appendChild(t); });\nwindow.__pdfJsLoaded = loadPdfJs();\nconst pdfWorker = () => { pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js'; };\n(async () => {\n  const user = await boot();\n  const main = document.getElementById('main');\n  let ch;\n  try { ch = await api('/api/chapters/' + encodeURIComponent(qs('id'))); }\n  catch (e) { main.innerHTML = `<div class=\"wrap empty\" style=\"margin:5rem auto\">${esc(e.message)}<br><br><a class=\"btn\" href=\"/\">Back home</a></div>`; return; }\n\n  document.title = `${ch.comicTitle} Ch. ${ch.number} · Morgan.stdio`;\n  const bar = document.getElementById('bar'); bar.classList.remove('hidden');\n  document.getElementById('backLink').href = '/comic?id=' + ch.comicId;\n  document.getElementById('backLink').textContent = '← ' + ch.comicTitle;\n  document.getElementById('chTitle').textContent = `Chapter ${ch.number}: ${ch.title}`;\n  const navBtn = (el, id) => { if (id) el.href = '/read?id=' + id; else { el.removeAttribute('href'); el.style.opacity = .35; el.style.pointerEvents = 'none'; } };\n  navBtn(document.getElementById('prevBtn'), ch.prev);\n  navBtn(document.getElementById('nextBtn'), ch.next);\n\n  // ── Paywall ──\n  if (ch.locked) {\n    const next = encodeURIComponent(location.pathname + location.search);\n    main.innerHTML = `<div class=\"wrap\"><div class=\"paywall panel halftone\">\n      <div class=\"big\">🔒</div>\n      <h1 class=\"display\" style=\"font-size:2.6rem\">Members Only Chapter</h1>\n      <p class=\"muted\" style=\"margin:.6rem 0 1.6rem\">Subscribe to read <b style=\"color:#fff\">${esc(ch.comicTitle)}, Chapter ${ch.number}</b> and every other chapter on Morgan.stdio.</p>\n      <div style=\"display:flex;gap:.8rem;justify-content:center;flex-wrap:wrap\">\n        <a class=\"btn yellow\" href=\"/subscribe?next=${next}\">Subscribe · from $2 or 500 CFA</a>\n        ${!user ? `<a class=\"btn ghost\" href=\"/login?next=${next}\">I already have an account</a>` : ''}\n      </div></div></div>`;\n    return;\n  }\n\n  const showEndNav = () => {\n    const end = document.getElementById('endNav'); end.classList.remove('hidden');\n    end.innerHTML = `${ch.prev ? `<a class=\"btn ghost\" href=\"/read?id=${ch.prev}\">‹ Previous Chapter</a>` : ''}\n      ${ch.next ? `<a class=\"btn\" href=\"/read?id=${ch.next}\">Next Chapter ›</a>` : `<a class=\"btn ghost\" href=\"/comic?id=${ch.comicId}\">You're all caught up! Back to series</a>`}`;\n  };\n\n  // ── Webtoon chapter: one long vertical scroll ──\n  if (ch.type === 'images' && ch.style === 'webtoon') {\n    document.getElementById('pageInfo').textContent = `${ch.pageCount} parts`;\n    main.innerHTML = `<div class=\"webtoon\" id=\"webtoon\"></div>`;\n    const col = document.getElementById('webtoon');\n    const token = Auth.token ? '?token=' + encodeURIComponent(Auth.token) : '';\n    for (let i = 1; i <= ch.pageCount; i++) {\n      const img = document.createElement('img');\n      img.src = `/api/chapters/${ch.id}/page/${i}${token}`;\n      img.loading = 'lazy'; img.alt = 'Part ' + i; img.dataset.n = i;\n      col.appendChild(img);\n    }\n    const info = document.getElementById('pageInfo');\n    const wo = new IntersectionObserver(es => es.forEach(e => {\n      if (e.isIntersecting && e.intersectionRatio > .2) info.textContent = `Part ${e.target.dataset.n} / ${ch.pageCount}`;\n    }), { threshold: [.2] });\n    [...col.children].forEach(img => wo.observe(img));\n    const prog = document.getElementById('progress');\n    addEventListener('scroll', () => { const h = document.documentElement; prog.style.width = (h.scrollTop / (h.scrollHeight - h.clientHeight) * 100) + '%'; });\n    showEndNav();\n    return;\n  }\n\n  // ── Picture chapter: one page at a time, full screen, swipe like a book (left to right) ──\n  if (ch.type === 'images') {\n    document.getElementById('pageInfo').textContent = `${ch.pageCount} pages`;\n    main.innerHTML = `\n      <div class=\"manga\" id=\"manga\"></div>\n      <div class=\"pageNav\">\n        <button class=\"btn ghost sm\" id=\"prevPage\" aria-label=\"Previous page\">‹</button>\n        <span id=\"pageLabel\" style=\"font-size:.9rem\"></span>\n        <button class=\"btn sm\" id=\"nextPage\" aria-label=\"Next page\">›</button>\n      </div>\n      <a class=\"btn yellow nextCh hidden\" id=\"nextCh\"></a>`;\n    const strip = document.getElementById('manga');\n    const token = Auth.token ? '?token=' + encodeURIComponent(Auth.token) : '';\n    const zoom = src => {\n      const z = document.createElement('div');\n      z.id = 'zoomView';\n      z.innerHTML = `<img src=\"${src}\" alt=\"\">`;\n      z.onclick = () => z.remove();\n      document.body.appendChild(z);\n    };\n    for (let i = 1; i <= ch.pageCount; i++) {\n      const img = document.createElement('img');\n      img.src = `/api/chapters/${ch.id}/page/${i}${token}`;\n      img.loading = 'lazy'; img.alt = 'Page ' + i; img.dataset.n = i;\n      img.onclick = () => zoom(img.src);\n      strip.appendChild(img);\n    }\n    const go = dir => strip.scrollBy({ left: dir * strip.clientWidth, behavior: 'smooth' });\n    document.getElementById('nextPage').onclick = () => go(1);\n    document.getElementById('prevPage').onclick = () => go(-1);\n    addEventListener('keydown', e => {\n      if (e.key === 'ArrowRight') { go(1); e.preventDefault(); }\n      if (e.key === 'ArrowLeft') { go(-1); e.preventDefault(); }\n    });\n    const label = document.getElementById('pageLabel');\n    const nextCh = document.getElementById('nextCh');\n    const po = new IntersectionObserver(es => es.forEach(e => {\n      if (e.isIntersecting && e.intersectionRatio > .5) {\n        const n = +e.target.dataset.n;\n        label.textContent = `${n} / ${ch.pageCount}`;\n        document.getElementById('pageInfo').textContent = `Page ${n} / ${ch.pageCount}`;\n        if (n === ch.pageCount) {\n          nextCh.innerHTML = ch.next ? 'Next chapter ›' : '✓ Back to series';\n          nextCh.href = ch.next ? '/read?id=' + ch.next : '/comic?id=' + ch.comicId;\n          nextCh.classList.remove('hidden');\n        } else nextCh.classList.add('hidden');\n      }\n    }), { root: strip, threshold: [0.5] });\n    [...strip.children].forEach(img => po.observe(img));\n    const prog = document.getElementById('progress');\n    strip.addEventListener('scroll', () => {\n      const max = strip.scrollWidth - strip.clientWidth;\n      prog.style.width = (max > 0 ? strip.scrollLeft / max * 100 : 100) + '%';\n    });\n    return;\n  }\n\n  // ── PDF chapter: vertical scroll ──\n  main.innerHTML = `<div class=\"pages\" id=\"pages\"></div>`;\n  const pagesEl = document.getElementById('pages');\n  try {\n    await window.__pdfJsLoaded; pdfWorker();\n    const pdf = await pdfjsLib.getDocument({ url: `/api/chapters/${ch.id}/pdf`, httpHeaders: Auth.token ? { Authorization: 'Bearer ' + Auth.token } : {} }).promise;\n    document.getElementById('pageInfo').textContent = `${pdf.numPages} pages`;\n    const first = await pdf.getPage(1);\n    const vp1 = first.getViewport({ scale: 1 });\n    const ratio = vp1.height / vp1.width;\n\n    for (let i = 1; i <= pdf.numPages; i++) {\n      const div = document.createElement('div');\n      div.className = 'page'; div.dataset.n = i;\n      div.style.aspectRatio = `1 / ${ratio}`;\n      div.innerHTML = `<span>Page ${i}</span>`;\n      pagesEl.appendChild(div);\n    }\n    const render = async div => {\n      if (div.dataset.done) return; div.dataset.done = 1;\n      const page = await pdf.getPage(+div.dataset.n);\n      const width = div.clientWidth || pagesEl.clientWidth;\n      const scale = (width * Math.min(window.devicePixelRatio || 1, 2)) / page.getViewport({ scale: 1 }).width;\n      const vp = page.getViewport({ scale });\n      const canvas = document.createElement('canvas');\n      canvas.width = vp.width; canvas.height = vp.height;\n      canvas.oncontextmenu = e => e.preventDefault();\n      await page.render({ canvasContext: canvas.getContext('2d'), viewport: vp }).promise;\n      div.style.aspectRatio = ''; div.innerHTML = ''; div.appendChild(canvas);\n    };\n    const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { render(e.target); io.unobserve(e.target); } }), { rootMargin: '1200px 0px' });\n    pagesEl.querySelectorAll('.page').forEach(p => io.observe(p));\n\n    showEndNav();\n  } catch (e) {\n    main.innerHTML = `<div class=\"wrap empty\" style=\"margin:5rem auto\">Could not load this chapter. ${esc(e.message)}</div>`;\n  }\n\n  const prog = document.getElementById('progress');\n  addEventListener('scroll', () => { const h = document.documentElement; prog.style.width = (h.scrollTop / (h.scrollHeight - h.clientHeight) * 100) + '%'; });\n})();\n</script>\n</body>\n</html>\n"}, "/style.css": {"type": "text/css; charset=utf-8", "body": "@import url('https://fonts.googleapis.com/css2?family=Bangers&family=Inter:wght@400;500;600;700;800&display=swap');\n\n:root {\n  --bg: #0d0d17;\n  --bg2: #151524;\n  --card: #1b1b2e;\n  --line: #2b2b44;\n  --text: #f3f3f8;\n  --muted: #a3a3bd;\n  --red: #ff3d5a;\n  --yellow: #ffd23f;\n  --blue: #3dd6ff;\n  --green: #2ed47a;\n  --radius: 16px;\n}\n* { box-sizing: border-box; margin: 0; padding: 0; }\nhtml { scroll-behavior: smooth; }\nbody { font-family: 'Inter', system-ui, -apple-system, Segoe UI, Arial, sans-serif; background: var(--bg); color: var(--text); line-height: 1.55; min-height: 100vh; display: flex; flex-direction: column; }\nmain { flex: 1; }\na { color: inherit; text-decoration: none; }\nimg { max-width: 100%; display: block; }\nbutton { font: inherit; cursor: pointer; }\n.display { font-family: 'Bangers', Impact, 'Arial Black', sans-serif; letter-spacing: 1.5px; font-weight: 400; }\n.wrap { width: min(1200px, 92%); margin: 0 auto; }\n.muted { color: var(--muted); }\n.hidden { display: none !important; }\n\n/* ── Nav ── */\n.nav { position: sticky; top: 0; z-index: 50; background: rgba(13,13,23,.9); backdrop-filter: blur(10px); border-bottom: 1px solid var(--line); }\n.nav .wrap { display: flex; align-items: center; justify-content: space-between; height: 66px; gap: 1rem; }\n.brand { display: flex; align-items: center; gap: .6rem; font-weight: 800; font-size: 1.25rem; }\n.brand svg { width: 40px; height: 40px; flex-shrink: 0; }\n.brand b { color: var(--yellow); }\n.nav-links { display: flex; align-items: center; gap: 1.1rem; font-weight: 600; font-size: .95rem; }\n.nav-links a:not(.btn):hover { color: var(--yellow); }\n.pill { font-size: .72rem; font-weight: 800; padding: .2rem .55rem; border-radius: 20px; background: var(--green); color: #062; text-transform: uppercase; }\n.pill.admin { background: var(--yellow); color: #3a2a00; }\n\n/* ── Buttons ── */\n.btn { display: inline-flex; align-items: center; justify-content: center; gap: .45rem; padding: .7rem 1.35rem; border-radius: 12px; border: 2px solid transparent; font-weight: 700; font-size: .95rem; transition: transform .15s, filter .15s, background .15s; background: var(--red); color: #fff; white-space: nowrap; }\n.btn:hover { transform: translateY(-2px); filter: brightness(1.08); }\n.btn:disabled { opacity: .55; transform: none; cursor: not-allowed; }\n.btn.yellow { background: var(--yellow); color: #1a1400; }\n.btn.ghost { background: transparent; border-color: var(--line); color: var(--text); }\n.btn.ghost:hover { border-color: var(--yellow); }\n.btn.sm { padding: .45rem .85rem; font-size: .85rem; border-radius: 9px; }\n.btn.block { width: 100%; }\n.btn.danger { background: #3a1520; color: #ff8b9c; border-color: #5a2030; }\n\n/* ── Hero / featured advert carousel ── */\n.hero { position: relative; overflow: hidden; border-bottom: 1px solid var(--line); }\n.slides { position: relative; height: min(78vh, 620px); min-height: 440px; }\n.slide { position: absolute; inset: 0; opacity: 0; transition: opacity .8s ease; display: flex; align-items: flex-end; }\n.slide.active { opacity: 1; z-index: 1; }\n.slide .bg { position: absolute; inset: 0; background-size: cover; background-position: center; transform: scale(1.06); transition: transform 7s ease; filter: saturate(1.1); }\n.slide.active .bg { transform: scale(1); }\n.slide::after { content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(13,13,23,.96) 0%, rgba(13,13,23,.75) 45%, rgba(13,13,23,.15) 100%), linear-gradient(0deg, var(--bg) 0%, transparent 35%); }\n.slide .content { position: relative; z-index: 2; padding: 0 0 4.5rem; max-width: 620px; }\n.badge-new { display: inline-flex; align-items: center; gap: .4rem; background: var(--red); color: #fff; font-weight: 800; font-size: .8rem; padding: .35rem .8rem; border-radius: 8px; text-transform: uppercase; letter-spacing: 1px; box-shadow: 4px 4px 0 #000; transform: rotate(-2deg); }\n.badge-new .dot { width: 8px; height: 8px; border-radius: 50%; background: #fff; animation: pulse 1.2s infinite; }\n@keyframes pulse { 50% { opacity: .2; } }\n.slide h1 { font-size: clamp(2.6rem, 6vw, 4.6rem); line-height: 1; margin: 1rem 0 .3rem; text-shadow: 4px 4px 0 #000; }\n.slide h2 { font-size: 1.25rem; color: var(--yellow); margin-bottom: .8rem; font-weight: 700; }\n.slide p { color: #d6d6e4; margin-bottom: 1.6rem; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }\n.slide .actions { display: flex; gap: .8rem; flex-wrap: wrap; }\n.dots { position: absolute; bottom: 1.6rem; left: 0; right: 0; z-index: 3; }\n.dots .wrap { display: flex; gap: .5rem; }\n.dots button { width: 34px; height: 6px; border-radius: 4px; border: none; background: rgba(255,255,255,.3); }\n.dots button.active { background: var(--yellow); }\n\n.hero-empty { padding: 7rem 0 6rem; text-align: center; background: radial-gradient(circle at 20% 20%, rgba(255,61,90,.25), transparent 40%), radial-gradient(circle at 80% 60%, rgba(61,214,255,.18), transparent 40%); }\n.hero-empty h1 { font-size: clamp(3rem, 8vw, 5.5rem); text-shadow: 5px 5px 0 #000; }\n\n/* halftone accent */\n.halftone { background-image: radial-gradient(rgba(255,255,255,.07) 1.2px, transparent 1.3px); background-size: 14px 14px; }\n\n/* ── Sections ── */\nsection.block { padding: 3.5rem 0; }\n.sec-head { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 1.5rem; gap: 1rem; flex-wrap: wrap; }\n.sec-head h2 { font-size: 2.2rem; }\n.sec-head h2 span { color: var(--red); }\n\n/* latest chapter strip */\n.strip { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(260px, 300px); gap: 1rem; overflow-x: auto; padding-bottom: .8rem; scroll-snap-type: x mandatory; }\n.strip::-webkit-scrollbar { height: 8px; } .strip::-webkit-scrollbar-thumb { background: var(--line); border-radius: 4px; }\n.chip { scroll-snap-align: start; display: flex; gap: .9rem; background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: .7rem; transition: border-color .2s, transform .2s; }\n.chip:hover { border-color: var(--yellow); transform: translateY(-3px); }\n.chip .thumb { width: 64px; height: 86px; border-radius: 8px; flex-shrink: 0; background-size: cover; background-position: center; }\n.chip h4 { font-size: .98rem; line-height: 1.25; }\n.chip .sm { font-size: .82rem; color: var(--muted); }\n\n/* comics grid */\n.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 1.4rem; }\n.comic { position: relative; border-radius: var(--radius); overflow: hidden; background: var(--card); border: 1px solid var(--line); transition: transform .2s, box-shadow .2s; }\n.comic:hover { transform: translateY(-6px) rotate(-.4deg); box-shadow: 8px 8px 0 var(--red); }\n.comic .cover { aspect-ratio: 3 / 4; background-size: cover; background-position: center; }\n.comic .info { padding: .8rem .9rem 1rem; }\n.comic h3 { font-size: 1.05rem; line-height: 1.25; }\n.comic .sm { font-size: .82rem; color: var(--muted); margin-top: .2rem; }\n.tag { position: absolute; top: .7rem; left: .7rem; font-size: .7rem; font-weight: 800; text-transform: uppercase; padding: .25rem .55rem; border-radius: 6px; background: var(--red); color: #fff; box-shadow: 3px 3px 0 #000; }\n.tag.genre { left: auto; right: .7rem; background: rgba(0,0,0,.65); box-shadow: none; }\n\n/* generated cover (no image) */\n.gen-cover { display: flex; align-items: center; justify-content: center; text-align: center; padding: 1rem; font-family: 'Bangers', Impact, sans-serif; font-size: 1.8rem; letter-spacing: 1px; line-height: 1.05; text-shadow: 3px 3px 0 #000; }\n\n/* pricing */\n.plans { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 1.4rem; }\n.plan { position: relative; background: var(--card); border: 2px solid var(--line); border-radius: 20px; padding: 1.8rem 1.6rem; cursor: pointer; transition: border-color .2s, transform .2s; }\n.plan:hover { transform: translateY(-4px); }\n.plan.selected { border-color: var(--yellow); box-shadow: 6px 6px 0 var(--yellow); }\n.plan h3 { font-size: 1.15rem; }\n.plan .price { font-size: 2.7rem; font-weight: 800; margin: .4rem 0 0; }\n.plan .price small { font-size: 1rem; color: var(--muted); font-weight: 600; }\n.plan ul { list-style: none; margin-top: 1rem; display: grid; gap: .45rem; font-size: .93rem; color: #d0d0e0; }\n.plan li::before { content: '✓ '; color: var(--green); font-weight: 800; }\n.plan .ribbon { position: absolute; top: -12px; right: 16px; background: var(--red); color: #fff; font-size: .75rem; font-weight: 800; padding: .25rem .7rem; border-radius: 8px; box-shadow: 3px 3px 0 #000; }\n\n.methods { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: .8rem; margin: 1rem 0; }\n.method { display: flex; align-items: center; gap: .7rem; padding: .9rem 1rem; border: 2px solid var(--line); border-radius: 12px; background: var(--bg2); cursor: pointer; font-weight: 600; }\n.method.selected { border-color: var(--yellow); }\n.method .logo { width: 38px; height: 26px; border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: .65rem; font-weight: 900; }\n\n/* forms */\n.panel { background: var(--card); border: 1px solid var(--line); border-radius: 20px; padding: 2rem; }\nlabel { display: block; font-weight: 600; font-size: .9rem; margin-bottom: .35rem; }\ninput[type=text], input[type=email], input[type=password], input[type=number], input[type=tel], select, textarea {\n  width: 100%; padding: .8rem 1rem; border-radius: 11px; border: 2px solid var(--line); background: var(--bg2); color: var(--text); font: inherit; }\ninput:focus, select:focus, textarea:focus { outline: none; border-color: var(--yellow); }\ninput[type=file] { width: 100%; padding: .7rem; border: 2px dashed var(--line); border-radius: 11px; background: var(--bg2); color: var(--muted); }\n.field { margin-bottom: 1rem; }\n.row { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }\n.check { display: flex; align-items: center; gap: .55rem; font-weight: 600; cursor: pointer; margin-bottom: .6rem; }\n.check input { width: 18px; height: 18px; accent-color: var(--yellow); }\n.error { background: #3a1520; color: #ff9aa9; border: 1px solid #5a2030; padding: .7rem 1rem; border-radius: 10px; margin-bottom: 1rem; font-size: .92rem; }\n.success { background: #0f3324; color: #7ff0b5; border: 1px solid #1d5a3e; padding: .7rem 1rem; border-radius: 10px; margin-bottom: 1rem; font-size: .92rem; }\n.notice { background: rgba(255,210,63,.1); border: 1px solid rgba(255,210,63,.35); color: #ffe48a; padding: .8rem 1rem; border-radius: 12px; font-size: .9rem; }\n\n/* tabs */\n.tabs { display: flex; gap: .4rem; flex-wrap: wrap; border-bottom: 1px solid var(--line); margin-bottom: 1.6rem; }\n.tabs button { background: none; border: none; color: var(--muted); padding: .8rem 1.1rem; font-weight: 700; border-bottom: 3px solid transparent; }\n.tabs button.active { color: var(--text); border-bottom-color: var(--yellow); }\n\n/* tables */\n.table-wrap { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; font-size: .9rem; }\nth, td { text-align: left; padding: .75rem .7rem; border-bottom: 1px solid var(--line); vertical-align: middle; }\nth { color: var(--muted); font-weight: 600; font-size: .8rem; text-transform: uppercase; letter-spacing: .5px; }\n.status { font-size: .75rem; font-weight: 800; padding: .2rem .55rem; border-radius: 6px; text-transform: uppercase; }\n.status.success, .status.active { background: #0f3324; color: #7ff0b5; }\n.status.pending { background: #3a3010; color: #ffe48a; }\n.status.failed, .status.none { background: #3a1520; color: #ff9aa9; }\n\n.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 1rem; margin-bottom: 2rem; }\n.stat { background: var(--card); border: 1px solid var(--line); border-radius: 16px; padding: 1.2rem 1.3rem; }\n.stat .n { font-size: 2rem; font-weight: 800; }\n.stat .l { color: var(--muted); font-size: .85rem; font-weight: 600; }\n\n/* chapter list */\n.chapters { display: grid; gap: .7rem; }\n.chapter { display: flex; align-items: center; justify-content: space-between; gap: 1rem; background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 1rem 1.2rem; transition: border-color .2s; }\n.chapter:hover { border-color: var(--yellow); }\n.chapter .num { font-family: 'Bangers', Impact, sans-serif; font-size: 1.6rem; color: var(--yellow); width: 54px; flex-shrink: 0; }\n.chapter .t { flex: 1; min-width: 0; }\n.chapter .t h4 { font-size: 1rem; }\n.chapter .t .sm { font-size: .82rem; color: var(--muted); }\n.mini { font-size: .7rem; font-weight: 800; padding: .2rem .5rem; border-radius: 6px; text-transform: uppercase; margin-left: .4rem; vertical-align: middle; }\n.mini.free { background: #0f3324; color: #7ff0b5; }\n.mini.new { background: var(--red); color: #fff; }\n.mini.lock { background: #2a2a40; color: var(--muted); }\n\n/* comic detail header */\n.detail { display: grid; grid-template-columns: 260px 1fr; gap: 2.2rem; align-items: start; padding: 3rem 0 2rem; }\n.detail .cover { aspect-ratio: 3/4; border-radius: 18px; background-size: cover; background-position: center; box-shadow: 10px 10px 0 var(--red); }\n.detail h1 { font-size: clamp(2.4rem, 5vw, 3.6rem); line-height: 1; text-shadow: 3px 3px 0 #000; }\n\n/* reader */\n.reader-bar { position: sticky; top: 66px; z-index: 40; background: rgba(21,21,36,.95); backdrop-filter: blur(8px); border-bottom: 1px solid var(--line); }\n.reader-bar .wrap { display: flex; align-items: center; justify-content: space-between; gap: 1rem; height: 58px; }\n.pages { width: min(900px, 100%); margin: 1.5rem auto 3rem; display: grid; gap: 6px; }\n.page { background: #0a0a12; min-height: 300px; display: flex; align-items: center; justify-content: center; color: var(--muted); border-radius: 4px; overflow: hidden; }\n.page canvas { width: 100%; height: auto; display: block; -webkit-user-select: none; user-select: none; }\n.paywall { max-width: 560px; margin: 4rem auto; text-align: center; }\n.paywall .big { font-size: 4rem; }\n.progress { position: fixed; top: 0; left: 0; height: 3px; background: var(--yellow); z-index: 60; width: 0; }\n\n/* modal */\n.modal { position: fixed; inset: 0; z-index: 100; background: rgba(0,0,0,.72); display: flex; align-items: center; justify-content: center; padding: 1rem; animation: fade .25s; }\n@keyframes fade { from { opacity: 0; } }\n.modal .box { position: relative; background: var(--card); border: 2px solid var(--yellow); border-radius: 22px; width: min(520px, 100%); max-height: 90vh; overflow: auto; box-shadow: 10px 10px 0 var(--red); animation: pop .35s cubic-bezier(.2,1.4,.4,1); }\n@keyframes pop { from { transform: scale(.85); opacity: 0; } }\n.modal .x { position: absolute; top: .7rem; right: .7rem; width: 36px; height: 36px; border-radius: 50%; border: none; background: rgba(0,0,0,.6); color: #fff; font-size: 1.2rem; z-index: 2; }\n.modal .art { aspect-ratio: 16/9; background-size: cover; background-position: center; border-radius: 20px 20px 0 0; position: relative; }\n.modal .art .badge-new { position: absolute; left: 1rem; bottom: -14px; }\n.modal .body { padding: 1.8rem 1.6rem 1.6rem; }\n\n/* toast */\n#toast { position: fixed; bottom: 1.5rem; left: 50%; transform: translateX(-50%) translateY(150%); background: var(--yellow); color: #1a1400; font-weight: 700; padding: .8rem 1.4rem; border-radius: 12px; box-shadow: 4px 4px 0 #000; z-index: 200; transition: transform .3s; max-width: 90%; }\n#toast.show { transform: translateX(-50%) translateY(0); }\n#toast.err { background: var(--red); color: #fff; }\n\nfooter { border-top: 1px solid var(--line); padding: 2rem 0; color: var(--muted); font-size: .9rem; margin-top: 2rem; }\nfooter .wrap { display: flex; justify-content: space-between; align-items: center; gap: 1rem; flex-wrap: wrap; }\n\n.empty { text-align: center; padding: 3rem 1rem; color: var(--muted); border: 2px dashed var(--line); border-radius: 18px; }\n.spinner { width: 36px; height: 36px; border: 4px solid var(--line); border-top-color: var(--yellow); border-radius: 50%; animation: spin .8s linear infinite; margin: 2rem auto; }\n@keyframes spin { to { transform: rotate(360deg); } }\n\n@media (max-width: 760px) {\n  .hide-sm { display: none !important; }\n  .brand span.txt { font-size: 1.05rem; }\n  .detail { grid-template-columns: 1fr; }\n  .detail .cover { max-width: 230px; }\n  .row { grid-template-columns: 1fr; }\n  .slide::after { background: linear-gradient(0deg, rgba(13,13,23,.98) 10%, rgba(13,13,23,.55) 60%, rgba(13,13,23,.2) 100%); }\n  .panel { padding: 1.3rem; }\n  .grid { grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 1rem; }\n}\n\n/* ── Picture chapter reader: one page per screen, swipe like a book ── */\n.manga{display:flex;overflow-x:auto;overflow-y:hidden;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;background:#05050a;width:100vw;height:calc(100vh - 118px);scrollbar-width:none}\n@supports (height:100dvh){.manga{height:calc(100dvh - 118px)}}\n.manga::-webkit-scrollbar{display:none}\n.manga img{flex:0 0 100vw;width:100vw;height:100%;object-fit:contain;scroll-snap-align:center;scroll-snap-stop:always;background:#05050a;user-select:none;-webkit-user-drag:none}\n.pageNav{position:fixed;left:50%;transform:translateX(-50%);bottom:14px;display:flex;gap:.8rem;align-items:center;background:rgba(10,10,18,.85);border:1px solid rgba(255,255,255,.14);padding:.35rem .9rem;border-radius:999px;z-index:50}\n.nextCh{position:fixed;right:14px;bottom:70px;z-index:50}\n#zoomView{position:fixed;inset:0;background:#000;z-index:60;overflow-y:auto;-webkit-overflow-scrolling:touch}\n#zoomView img{width:100vw;display:block}\n\n/* ── Picture picker thumbnails (admin upload) ── */\n.thumbs{margin:-.4rem 0 1rem}\n.thumb-note{font-size:.85rem;color:var(--muted,#9aa);margin-bottom:.5rem;line-height:1.45}\n.thumb-list{display:flex;flex-wrap:wrap;gap:.6rem}\n.thumb{width:76px;text-align:center}\n.thumb img{width:76px;height:100px;object-fit:cover;border-radius:8px;border:2px solid var(--line,#2a2a3a);display:block}\n.thumb .tnum{position:relative;display:inline-block;margin-top:-1.4rem;background:var(--yellow,#ffd60a);color:#111;font-weight:700;font-size:.75rem;border-radius:6px;padding:.05rem .4rem}\n.thumb .tctl{display:flex;gap:.2rem;justify-content:center;margin-top:.3rem}\n.thumb .tctl button{background:var(--line,#2a2a3a);color:#fff;border:0;border-radius:6px;padding:.15rem .45rem;font-size:.8rem;cursor:pointer}\n.thumb .tctl button:disabled{opacity:.3;cursor:default}\n\n/* ── Webtoon reader: one long vertical scroll ── */\n.webtoon{max-width:820px;margin:0 auto;background:#05050a}\n.webtoon img{width:100%;display:block;user-select:none;-webkit-user-drag:none}\n"}, "/subscribe.html": {"type": "text/html; charset=utf-8", "body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Subscribe · Morgan.stdio</title>\n<link rel=\"icon\" href=\"/logo.svg\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n<nav id=\"nav\"></nav>\n<main class=\"wrap\" style=\"padding:3rem 0 2rem\">\n  <div style=\"text-align:center;margin-bottom:2.5rem\">\n    <h1 class=\"display\" style=\"font-size:clamp(2.6rem,6vw,4rem);text-shadow:4px 4px 0 #000\">Unlock <span style=\"color:var(--yellow)\">Every</span> Chapter</h1>\n    <p class=\"muted\" style=\"font-size:1.1rem\">Choose a plan. Pay with Mobile Money, card or PayPal. Cancel any time.</p>\n  </div>\n  <div id=\"status\"></div>\n  <div class=\"plans\" id=\"plans\"><div class=\"spinner\"></div></div>\n\n  <div class=\"panel hidden\" id=\"payBox\" style=\"margin-top:2rem;max-width:720px;margin-left:auto;margin-right:auto\">\n    <h2 style=\"font-size:1.3rem\">2. Choose how to pay</h2>\n    <div class=\"methods\" id=\"methods\"></div>\n    <div class=\"field hidden\" id=\"phoneField\"><label>Mobile Money number</label><input type=\"tel\" id=\"phone\" placeholder=\"e.g. 6 7X XX XX XX\"></div>\n    <div id=\"payMsg\"></div>\n    <button class=\"btn yellow block\" id=\"payBtn\">Pay</button>\n    <p class=\"muted\" style=\"font-size:.82rem;text-align:center;margin-top:.8rem\" id=\"modeNote\"></p>\n  </div>\n</main>\n<footer id=\"footer\"></footer>\n<script src=\"/app.js\"></script>\n<script>\nconst METHOD_STYLE = {\n  mtn: 'background:#ffcc00;color:#000', orange: 'background:#ff6600;color:#fff',\n  card: 'background:#1a1f71;color:#fff', paypal: 'background:#003087;color:#fff',\n};\nconst METHOD_SHORT = { mtn: 'MTN', orange: 'OM', card: 'VISA', paypal: 'PP' };\n(async () => {\n  const user = await boot();\n  const { mode, plans, methods } = await api('/api/plans');\n  const next = qs('next');\n  let plan = null, method = null;\n\n  if (user && user.subscribed) {\n    document.getElementById('status').innerHTML = user.role === 'admin'\n      ? `<div class=\"success\" style=\"text-align:center\">You're the admin, so you can read everything already.</div>`\n      : `<div class=\"success\" style=\"text-align:center\">✅ You're a member until <b>${fmtDate(user.subscription.expiresAt)}</b>. Paying again will add more time.</div>`;\n  }\n\n  const perks = ['Every comic & chapter', 'New chapters as soon as they drop', 'Read on phone or computer'];\n  document.getElementById('plans').innerHTML = plans.map(p => `\n    <div class=\"plan\" data-id=\"${p.id}\">\n      ${p.badge ? `<span class=\"ribbon\">${p.badge}</span>` : ''}\n      <h3>${p.name}</h3>\n      <div class=\"price\">${p.label}<small> / ${p.per}</small></div>\n      <div class=\"muted\" style=\"font-size:.88rem\">${p.methods.map(m => methods[m].name).join(' · ')}</div>\n      <ul>${perks.map(x => `<li>${x}</li>`).join('')}</ul>\n      <button class=\"btn ${p.id === 'momo' ? 'yellow' : ''} block\" style=\"margin-top:1.3rem\">Choose ${p.name}</button>\n    </div>`).join('');\n\n  const payBox = document.getElementById('payBox');\n  document.querySelectorAll('.plan').forEach(el => el.onclick = () => {\n    if (!user) { location.href = '/login?mode=register&next=' + encodeURIComponent('/subscribe' + location.search); return; }\n    plan = plans.find(p => p.id === el.dataset.id); method = null;\n    document.querySelectorAll('.plan').forEach(x => x.classList.toggle('selected', x === el));\n    document.getElementById('methods').innerHTML = plan.methods.map(m => `\n      <div class=\"method\" data-m=\"${m}\"><span class=\"logo\" style=\"${METHOD_STYLE[m]}\">${METHOD_SHORT[m]}</span>${methods[m].name}</div>`).join('');\n    document.querySelectorAll('.method').forEach(mEl => mEl.onclick = () => {\n      method = mEl.dataset.m;\n      document.querySelectorAll('.method').forEach(x => x.classList.toggle('selected', x === mEl));\n      document.getElementById('phoneField').classList.toggle('hidden', !methods[method].needsPhone);\n    });\n    document.querySelector('.method').click();\n    document.getElementById('payBtn').textContent = `Pay ${money(plan.price, plan.currency)}`;\n    document.getElementById('payMsg').innerHTML = '';\n    payBox.classList.remove('hidden');\n    payBox.scrollIntoView({ behavior: 'smooth', block: 'center' });\n  });\n\n  document.getElementById('modeNote').textContent = mode === 'demo'\n    ? '⚠️ Demo mode: no real money is charged. Real payments will be switched on soon.'\n    : '🔒 Secure payment.';\n\n  document.getElementById('payBtn').onclick = async () => {\n    const btn = document.getElementById('payBtn'), msg = document.getElementById('payMsg');\n    msg.innerHTML = ''; btn.disabled = true;\n    try {\n      const r = await api('/api/checkout', { body: { plan: plan.id, method, phone: document.getElementById('phone').value } });\n      if (r.mode === 'redirect') { location.href = r.url; return; }\n      // Demo checkout pop-up\n      const m = document.createElement('div'); m.className = 'modal';\n      m.innerHTML = `<div class=\"box\"><div class=\"body\" style=\"text-align:center\">\n        <div style=\"font-size:3rem\">💳</div>\n        <h2 class=\"display\" style=\"font-size:2rem\">Demo Payment</h2>\n        <p class=\"muted\" style=\"margin:.5rem 0 1rem\">${esc(plan.name)} plan · <b style=\"color:#fff\">${money(plan.price, plan.currency)}</b> via ${esc(methods[method].name)}<br>Ref: ${esc(r.reference)}</p>\n        <div class=\"notice\" style=\"margin-bottom:1.2rem\">This is a test. No money will be taken. When real payments are connected, this step will open MTN MoMo, Orange Money, card or PayPal.</div>\n        <button class=\"btn yellow block\" id=\"ok\">✓ Simulate Successful Payment</button>\n        <button class=\"btn ghost block\" id=\"cancel\" style=\"margin-top:.6rem\">Cancel</button></div></div>`;\n      document.body.appendChild(m);\n      m.querySelector('#cancel').onclick = () => { m.remove(); btn.disabled = false; };\n      m.querySelector('#ok').onclick = async () => {\n        try {\n          await api(`/api/checkout/${r.reference}/demo-confirm`, { method: 'POST' });\n          m.querySelector('.body').innerHTML = `<div style=\"font-size:3.5rem\">🎉</div><h2 class=\"display\" style=\"font-size:2.2rem\">You're In!</h2>\n            <p class=\"muted\" style=\"margin:.5rem 0 1.4rem\">Your subscription is active. Enjoy every chapter!</p>\n            <a class=\"btn yellow block\" href=\"${esc(next || '/')}\">Start Reading →</a>`;\n        } catch (e) { toast(e.message, true); }\n      };\n    } catch (e) { msg.innerHTML = `<div class=\"error\">${esc(e.message)}</div>`; btn.disabled = false; }\n  };\n})();\n</script>\n</body>\n</html>\n"}};

// ── Small helpers ──
const json = (data, status = 200) => new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' } });
const err = (msg, status = 400) => json({ error: msg }, status);
const nowIso = () => new Date().toISOString();
const hex = bytes => [...bytes].map(b => b.toString(16).padStart(2, '0')).join('');
const randHex = n => hex(crypto.getRandomValues(new Uint8Array(n)));
const newId = p => p + '_' + Date.now().toString(36) + randHex(4);
const bool = v => v === true || v === 1 || v === 'true' || v === 'on' || v === '1';
const fileUrl = key => key ? '/files/' + key : null;
const b64 = buf => btoa(String.fromCharCode(...new Uint8Array(buf)));
const unb64 = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));

async function hashPassword(pw, salt = crypto.getRandomValues(new Uint8Array(16)), iter = PBKDF2_ITER) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(pw), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt, iterations: iter }, key, 256);
  return `pbkdf2$${iter}$${b64(salt)}$${b64(bits)}`;
}
async function verifyPassword(pw, stored) {
  const [kind, iter, salt, hash] = String(stored || '').split('$');
  if (kind !== 'pbkdf2') return false;
  const test = (await hashPassword(pw, unb64(salt), Number(iter))).split('$')[3];
  if (test.length !== hash.length) return false;
  let diff = 0; for (let i = 0; i < test.length; i++) diff |= test.charCodeAt(i) ^ hash.charCodeAt(i);
  return diff === 0;
}

// ── Database setup (runs automatically) ──
const SCHEMA = [
  `CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT, email TEXT UNIQUE, password_hash TEXT, role TEXT DEFAULT 'reader',
     sub_plan TEXT, sub_plan_name TEXT, sub_started TEXT, sub_expires TEXT, created_at TEXT)`,
  `CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id TEXT, created_at TEXT)`,
  `CREATE TABLE IF NOT EXISTS comics (id TEXT PRIMARY KEY, title TEXT, description TEXT, genre TEXT, cover TEXT, created_at TEXT)`,
  `CREATE TABLE IF NOT EXISTS chapters (id TEXT PRIMARY KEY, comic_id TEXT, number REAL, title TEXT, blurb TEXT, pdf TEXT, pages TEXT, style TEXT, banner TEXT,
     is_free INTEGER DEFAULT 0, featured INTEGER DEFAULT 1, original_name TEXT, size INTEGER, created_at TEXT)`,
  `CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, reference TEXT UNIQUE, user_id TEXT, user_email TEXT, plan TEXT, plan_name TEXT,
     method TEXT, method_name TEXT, phone TEXT, amount REAL, currency TEXT, status TEXT, mode TEXT, created_at TEXT, paid_at TEXT)`,
  `CREATE INDEX IF NOT EXISTS idx_chapters_comic ON chapters(comic_id)`,
  `CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id)`,
];
let ready = null;
function init(env) {
  if (!ready) ready = (async () => {
    await env.DB.batch(SCHEMA.map(s => env.DB.prepare(s)));
    try { await env.DB.prepare(`ALTER TABLE chapters ADD COLUMN pages TEXT`).run(); } catch (e) { /* column already exists */ }
    try { await env.DB.prepare(`ALTER TABLE chapters ADD COLUMN style TEXT`).run(); } catch (e) { /* column already exists */ }
    const admin = await env.DB.prepare(`SELECT id FROM users WHERE role='admin' LIMIT 1`).first();
    if (!admin && env.ADMIN_PASSWORD) {
      await env.DB.prepare(`INSERT INTO users (id,name,email,password_hash,role,created_at) VALUES (?,?,?,?,?,?)`)
        .bind(newId('usr'), 'Admin', adminEmail(env), await hashPassword(env.ADMIN_PASSWORD), 'admin', nowIso()).run();
    }
  })().catch(e => { ready = null; throw e; });
  return ready;
}
const adminEmail = env => String(env.ADMIN_EMAIL || 'ayukchris8@gmail.com').toLowerCase();
const payMode = env => env.PAYMENT_MODE || 'demo';

// ── Users ──
const isSubscribed = u => !!u && (u.role === 'admin' || (u.sub_expires && new Date(u.sub_expires).getTime() > Date.now()));
const publicUser = u => u && ({
  id: u.id, name: u.name, email: u.email, role: u.role, subscribed: isSubscribed(u),
  subscription: u.sub_expires ? { plan: u.sub_plan, planName: u.sub_plan_name, startedAt: u.sub_started, expiresAt: u.sub_expires } : null,
  createdAt: u.created_at,
});
async function getUser(req, env) {
  const h = req.headers.get('Authorization') || '';
  let token = null;
  if (h.startsWith('Bearer ')) token = h.slice(7);
  else { try { token = new URL(req.url).searchParams.get('token'); } catch (e) {} }
  if (!token) return null;
  const u = await env.DB.prepare(`SELECT u.* FROM sessions s JOIN users u ON u.id = s.user_id WHERE s.token = ?`).bind(token).first();
  if (u) u._token = token;
  return u;
}
async function newSession(env, user) {
  const token = randHex(32);
  await env.DB.prepare(`INSERT INTO sessions (token,user_id,created_at) VALUES (?,?,?)`).bind(token, user.id, nowIso()).run();
  return token;
}
async function activate(env, user, plan) {
  const now = Date.now();
  const cur = user.sub_expires && new Date(user.sub_expires).getTime() > now ? new Date(user.sub_expires).getTime() : now;
  const started = cur > now && user.sub_started ? user.sub_started : nowIso();
  const expires = new Date(cur + plan.days * 86400000).toISOString();
  await env.DB.prepare(`UPDATE users SET sub_plan=?, sub_plan_name=?, sub_started=?, sub_expires=? WHERE id=?`).bind(plan.id, plan.name, started, expires, user.id).run();
  Object.assign(user, { sub_plan: plan.id, sub_plan_name: plan.name, sub_started: started, sub_expires: expires });
}

// ── Comics & chapters ──
const CH_SELECT = `SELECT ch.*, c.title AS comic_title, c.cover AS comic_cover, c.description AS comic_desc FROM chapters ch JOIN comics c ON c.id = ch.comic_id`;
const pageCount = ch => { try { return ch.pages ? JSON.parse(ch.pages).length : 0; } catch (e) { return 0; } };
const chapterInfo = (ch, user) => ({
  id: ch.id, comicId: ch.comic_id, comicTitle: ch.comic_title || '', number: ch.number, title: ch.title,
  type: pageCount(ch) ? 'images' : 'pdf', pageCount: pageCount(ch) || null, style: ch.style === 'webtoon' ? 'webtoon' : 'pages',
  isFree: !!ch.is_free, featured: !!ch.featured, createdAt: ch.created_at,
  cover: fileUrl(ch.comic_cover), banner: fileUrl(ch.banner || ch.comic_cover),
  locked: !(ch.is_free || isSubscribed(user)), blurb: ch.blurb || ch.comic_desc || '',
});
const COMIC_SELECT = `SELECT c.*, COUNT(ch.id) AS chapter_count, MAX(ch.created_at) AS latest_ch FROM comics c LEFT JOIN chapters ch ON ch.comic_id = c.id`;
const comicSummary = c => ({
  id: c.id, title: c.title, description: c.description || '', genre: c.genre || '', cover: fileUrl(c.cover),
  chapterCount: c.chapter_count || 0, latestAt: c.latest_ch || c.created_at, createdAt: c.created_at,
});
async function readBody(req) { try { return await req.json(); } catch (e) { return {}; } }

// ═══════════════ ROUTES ═══════════════
async function handleApi(req, env, url) {
  const p = url.pathname, m = req.method;
  const user = await getUser(req, env);
  const needUser = () => user ? null : err('Please log in first.', 401);
  const needAdmin = () => user && user.role === 'admin' ? null : err('Admin only.', 403);
  let mt;

  // ── Auth ──
  if (p === '/api/register' && m === 'POST') {
    const b = await readBody(req);
    const name = String(b.name || '').trim(), email = String(b.email || '').trim().toLowerCase(), password = String(b.password || '');
    if (!name || !/^\S+@\S+\.\S+$/.test(email)) return err('Please enter your name and a valid email.');
    if (password.length < 6) return err('Password must be at least 6 characters.');
    if (await env.DB.prepare(`SELECT id FROM users WHERE email=?`).bind(email).first()) return err('An account with this email already exists. Please log in.');
    const u = { id: newId('usr'), name, email, role: 'reader', created_at: nowIso() };
    await env.DB.prepare(`INSERT INTO users (id,name,email,password_hash,role,created_at) VALUES (?,?,?,?,?,?)`).bind(u.id, name, email, await hashPassword(password), 'reader', u.created_at).run();
    return json({ token: await newSession(env, u), user: publicUser(u) });
  }
  if (p === '/api/login' && m === 'POST') {
    const b = await readBody(req);
    const email = String(b.email || '').trim().toLowerCase(), pw = String(b.password || '');
    let u = await env.DB.prepare(`SELECT * FROM users WHERE email=?`).bind(email).first();
    if (!u && email === adminEmail(env)) {
      if (!env.ADMIN_PASSWORD) return err('Admin account is not set up yet. Add the ADMIN_PASSWORD secret in your Cloudflare Worker settings, then try again.');
      if (pw === env.ADMIN_PASSWORD || pw.trim() === env.ADMIN_PASSWORD) {
        // First login after the password was set: create the admin now.
        const a = { id: newId('usr'), name: 'Admin', email, role: 'admin', created_at: nowIso() };
        try {
          await env.DB.prepare(`INSERT INTO users (id,name,email,password_hash,role,created_at) VALUES (?,?,?,?,?,?)`)
            .bind(a.id, a.name, email, await hashPassword(env.ADMIN_PASSWORD), 'admin', a.created_at).run();
          return json({ token: await newSession(env, a), user: publicUser(a) });
        } catch (e) { u = await env.DB.prepare(`SELECT * FROM users WHERE email=?`).bind(email).first(); }
      }
    }
    const ok = u && (await verifyPassword(pw, u.password_hash) || (pw.trim() !== pw && await verifyPassword(pw.trim(), u.password_hash)));
    if (!ok) return err('Wrong email or password.', 401);
    return json({ token: await newSession(env, u), user: publicUser(u) });
  }
  if (p === '/api/logout' && m === 'POST') {
    if (user) await env.DB.prepare(`DELETE FROM sessions WHERE token=?`).bind(user._token).run();
    return json({ ok: true });
  }
  if (p === '/api/me' && m === 'GET') return json({ user: publicUser(user) || null });
  if (p === '/api/me/password' && m === 'POST') {
    const r = needUser(); if (r) return r;
    const b = await readBody(req);
    if (!await verifyPassword(String(b.current || ''), user.password_hash)) return err('Current password is wrong.');
    if (String(b.newPassword || '').length < 6) return err('New password must be at least 6 characters.');
    await env.DB.batch([
      env.DB.prepare(`UPDATE users SET password_hash=? WHERE id=?`).bind(await hashPassword(String(b.newPassword)), user.id),
      env.DB.prepare(`DELETE FROM sessions WHERE user_id=? AND token<>?`).bind(user.id, user._token),
    ]);
    return json({ ok: true });
  }
  if (p === '/api/me/payments' && m === 'GET') {
    const r = needUser(); if (r) return r;
    const { results } = await env.DB.prepare(`SELECT * FROM payments WHERE user_id=? ORDER BY created_at DESC`).bind(user.id).all();
    return json(results.map(paymentOut));
  }

  // ── Public comics ──
  if (p === '/api/comics' && m === 'GET') {
    const { results } = await env.DB.prepare(`${COMIC_SELECT} GROUP BY c.id`).all();
    return json(results.map(comicSummary).sort((a, b) => b.latestAt.localeCompare(a.latestAt)));
  }
  if ((mt = p.match(/^\/api\/comics\/([\w-]+)$/)) && m === 'GET') {
    const c = await env.DB.prepare(`${COMIC_SELECT} WHERE c.id=? GROUP BY c.id`).bind(mt[1]).first();
    if (!c) return err('Comic not found.', 404);
    const { results } = await env.DB.prepare(`${CH_SELECT} WHERE ch.comic_id=? ORDER BY ch.number ASC`).bind(c.id).all();
    return json({ ...comicSummary(c), chapters: results.map(ch => chapterInfo(ch, user)) });
  }
  if (p === '/api/featured' && m === 'GET') {
    const { results } = await env.DB.prepare(`${CH_SELECT} WHERE ch.featured=1 ORDER BY ch.created_at DESC LIMIT 6`).all();
    return json(results.map(ch => chapterInfo(ch, user)));
  }
  if (p === '/api/latest' && m === 'GET') {
    const { results } = await env.DB.prepare(`${CH_SELECT} ORDER BY ch.created_at DESC LIMIT 12`).all();
    return json(results.map(ch => chapterInfo(ch, user)));
  }
  if ((mt = p.match(/^\/api\/chapters\/([\w-]+)$/)) && m === 'GET') {
    const ch = await env.DB.prepare(`${CH_SELECT} WHERE ch.id=?`).bind(mt[1]).first();
    if (!ch) return err('Chapter not found.', 404);
    const { results: sib } = await env.DB.prepare(`SELECT id FROM chapters WHERE comic_id=? ORDER BY number ASC`).bind(ch.comic_id).all();
    const i = sib.findIndex(x => x.id === ch.id);
    return json({ ...chapterInfo(ch, user), prev: sib[i - 1] ? sib[i - 1].id : null, next: sib[i + 1] ? sib[i + 1].id : null });
  }
  if ((mt = p.match(/^\/api\/chapters\/([\w-]+)\/page\/(\d+)$/)) && m === 'GET') {
    const ch = await env.DB.prepare(`SELECT * FROM chapters WHERE id=?`).bind(mt[1]).first();
    if (!ch) return err('Chapter not found.', 404);
    if (!(ch.is_free || isSubscribed(user))) return err('Subscription required.', 402);
    const pages = ch.pages ? JSON.parse(ch.pages) : [];
    const key = pages[+mt[2] - 1];
    if (!key) return err('Page not found.', 404);
    const obj = await env.FILES.get(key);
    if (!obj) return err('Page image is missing. Please re-upload this chapter.', 404);
    return new Response(obj.body, { headers: { 'Content-Type': (obj.httpMetadata && obj.httpMetadata.contentType) || 'image/jpeg', 'Cache-Control': 'private, max-age=86400' } });
  }
  if ((mt = p.match(/^\/api\/chapters\/([\w-]+)\/pdf$/)) && m === 'GET') {
    const ch = await env.DB.prepare(`SELECT * FROM chapters WHERE id=?`).bind(mt[1]).first();
    if (!ch) return err('Chapter not found.', 404);
    if (!(ch.is_free || isSubscribed(user))) return err('Subscription required.', 402);
    const obj = await env.FILES.get(ch.pdf);
    if (!obj) return err('PDF file is missing. Please re-upload this chapter.', 404);
    return new Response(obj.body, { headers: { 'Content-Type': 'application/pdf', 'Content-Disposition': 'inline', 'Cache-Control': 'private, no-store', 'Content-Length': String(obj.size) } });
  }

  // ── Payments ──
  if (p === '/api/plans' && m === 'GET') return json({ mode: payMode(env), plans: Object.values(PLANS), methods: METHODS });
  if (p === '/api/checkout' && m === 'POST') {
    const r = needUser(); if (r) return r;
    const b = await readBody(req);
    const plan = PLANS[b.plan], method = METHODS[b.method];
    if (!plan) return err('Please choose a plan.');
    if (!method || !plan.methods.includes(method.id)) return err('Please choose a payment method for this plan.');
    const phone = String(b.phone || '').replace(/[^\d+]/g, '');
    if (method.needsPhone && phone.length < 8) return err('Please enter your Mobile Money number.');
    const pay = { id: newId('pay'), reference: 'MS-' + randHex(5).toUpperCase() };
    await env.DB.prepare(`INSERT INTO payments (id,reference,user_id,user_email,plan,plan_name,method,method_name,phone,amount,currency,status,mode,created_at)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(pay.id, pay.reference, user.id, user.email, plan.id, plan.name, method.id, method.name, phone || null, plan.price, plan.currency, 'pending', payMode(env), nowIso()).run();
    if (payMode(env) === 'demo') return json({ mode: 'demo', reference: pay.reference });
    // ── Real payment provider (e.g. NotchPay) gets connected here ──
    return err('Real payments are not connected yet.', 500);
  }
  if ((mt = p.match(/^\/api\/checkout\/([\w-]+)\/demo-confirm$/)) && m === 'POST') {
    const r = needUser(); if (r) return r;
    if (payMode(env) !== 'demo') return err('Demo payments are turned off.');
    const pay = await env.DB.prepare(`SELECT * FROM payments WHERE reference=? AND user_id=?`).bind(mt[1], user.id).first();
    if (!pay) return err('Payment not found.', 404);
    if (pay.status !== 'pending') return err('This payment was already processed.');
    await env.DB.prepare(`UPDATE payments SET status='success', paid_at=? WHERE id=?`).bind(nowIso(), pay.id).run();
    await activate(env, user, PLANS[pay.plan]);
    return json({ ok: true, user: publicUser(user) });
  }

  // ═══ ADMIN ═══
  if (p.startsWith('/api/admin/')) { const r = needAdmin(); if (r) return r; }

  // Upload a file straight to R2 (PDF, cover or banner). Body = the raw file.
  if (p === '/api/admin/upload' && m === 'PUT') {
    const type = url.searchParams.get('type');
    const name = url.searchParams.get('name') || '';
    const ctype = req.headers.get('Content-Type') || '';
    const size = Number(req.headers.get('Content-Length') || 0);
    if (!['pdf', 'cover', 'banner', 'page'].includes(type)) return err('Unknown upload type.');
    if (!size) return err('Empty file.');
    if (size > MAX_UPLOAD) return err('File is too large (max 100 MB).');
    if (type === 'pdf' && !(ctype === 'application/pdf' || /\.pdf$/i.test(name))) return err('Only PDF files are allowed for chapters.');
    if (type !== 'pdf' && !ctype.startsWith('image/')) return err('Only image files are allowed for covers and banners.');
    const ext = (name.match(/\.[a-z0-9]{1,5}$/i) || [type === 'pdf' ? '.pdf' : '.jpg'])[0].toLowerCase();
    const key = `${type}s/${randHex(12)}${ext}`;
    await env.FILES.put(key, req.body, { httpMetadata: { contentType: type === 'pdf' ? 'application/pdf' : ctype } });
    return json({ key, size, name });
  }

  if (p === '/api/admin/comics' && m === 'POST') {
    const b = await readBody(req);
    const title = String(b.title || '').trim();
    if (!title) return err('Comic title is required.');
    const id = newId('cmc');
    await env.DB.prepare(`INSERT INTO comics (id,title,description,genre,cover,created_at) VALUES (?,?,?,?,?,?)`)
      .bind(id, title, String(b.description || '').trim(), String(b.genre || '').trim(), validKey(b.cover, 'covers/'), nowIso()).run();
    return json(comicSummary(await env.DB.prepare(`${COMIC_SELECT} WHERE c.id=? GROUP BY c.id`).bind(id).first()));
  }
  if ((mt = p.match(/^\/api\/admin\/comics\/([\w-]+)$/))) {
    const c = await env.DB.prepare(`SELECT * FROM comics WHERE id=?`).bind(mt[1]).first();
    if (!c) return err('Comic not found.', 404);
    if (m === 'PUT') {
      const b = await readBody(req);
      const cover = validKey(b.cover, 'covers/');
      if (cover && c.cover) await env.FILES.delete(c.cover);
      await env.DB.prepare(`UPDATE comics SET title=?, description=?, genre=?, cover=? WHERE id=?`).bind(
        String(b.title ?? c.title).trim() || c.title, String(b.description ?? c.description).trim(), String(b.genre ?? c.genre).trim(), cover || c.cover, c.id).run();
      return json(comicSummary(await env.DB.prepare(`${COMIC_SELECT} WHERE c.id=? GROUP BY c.id`).bind(c.id).first()));
    }
    if (m === 'DELETE') {
      const { results } = await env.DB.prepare(`SELECT pdf, banner, pages FROM chapters WHERE comic_id=?`).bind(c.id).all();
      const keys = [c.cover, ...results.flatMap(x => [x.pdf, x.banner, ...(x.pages ? JSON.parse(x.pages) : [])])].filter(Boolean);
      if (keys.length) await env.FILES.delete(keys);
      await env.DB.batch([env.DB.prepare(`DELETE FROM chapters WHERE comic_id=?`).bind(c.id), env.DB.prepare(`DELETE FROM comics WHERE id=?`).bind(c.id)]);
      return json({ ok: true });
    }
  }
  if (p === '/api/admin/chapters' && m === 'GET') {
    const { results } = await env.DB.prepare(`${CH_SELECT} ORDER BY ch.created_at DESC`).all();
    return json(results.map(ch => ({ ...chapterInfo(ch, user), size: ch.size, originalName: ch.original_name })));
  }
  if (p === '/api/admin/chapters' && m === 'POST') {
    const b = await readBody(req);
    const c = await env.DB.prepare(`SELECT id FROM comics WHERE id=?`).bind(b.comicId || '').first();
    if (!c) return err('Please choose a comic.');
    const pdf = validKey(b.pdf, 'pdfs/');
    let pages = [];
    if (Array.isArray(b.pages)) pages = b.pages.filter(k => validKey(k, 'pages/'));
    if (pages.length > 500) return err('Max 500 pictures per chapter. Please split it into two chapters.');
    if (!pdf && !pages.length) return err('Please upload a PDF file or some pictures.');
    const last = await env.DB.prepare(`SELECT MAX(number) AS n FROM chapters WHERE comic_id=?`).bind(c.id).first();
    const number = Number(b.number) || ((last && last.n) || 0) + 1;
    const id = newId('chp');
    await env.DB.prepare(`INSERT INTO chapters (id,comic_id,number,title,blurb,pdf,pages,style,banner,is_free,featured,original_name,size,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(
      id, c.id, number, String(b.title || '').trim() || `Chapter ${number}`, String(b.blurb || '').trim(), pdf,
      pages.length ? JSON.stringify(pages) : null, b.style === 'webtoon' ? 'webtoon' : 'pages', validKey(b.banner, 'banners/'),
      bool(b.isFree) ? 1 : 0, b.featured === undefined || bool(b.featured) ? 1 : 0,
      String(b.originalName || (pages.length ? `${pages.length} pictures` : '')), Number(b.size) || 0, nowIso()).run();
    return json(chapterInfo(await env.DB.prepare(`${CH_SELECT} WHERE ch.id=?`).bind(id).first(), user));
  }
  if ((mt = p.match(/^\/api\/admin\/chapters\/([\w-]+)$/))) {
    const ch = await env.DB.prepare(`SELECT * FROM chapters WHERE id=?`).bind(mt[1]).first();
    if (!ch) return err('Chapter not found.', 404);
    if (m === 'PATCH') {
      const b = await readBody(req);
      await env.DB.prepare(`UPDATE chapters SET is_free=?, featured=?, title=?, number=? WHERE id=?`).bind(
        b.isFree !== undefined ? (bool(b.isFree) ? 1 : 0) : ch.is_free, b.featured !== undefined ? (bool(b.featured) ? 1 : 0) : ch.featured,
        b.title !== undefined && String(b.title).trim() ? String(b.title).trim() : ch.title, Number(b.number) || ch.number, ch.id).run();
      return json(chapterInfo(await env.DB.prepare(`${CH_SELECT} WHERE ch.id=?`).bind(ch.id).first(), user));
    }
    if (m === 'DELETE') {
      await env.FILES.delete([ch.pdf, ch.banner, ...(ch.pages ? JSON.parse(ch.pages) : [])].filter(Boolean));
      await env.DB.prepare(`DELETE FROM chapters WHERE id=?`).bind(ch.id).run();
      return json({ ok: true });
    }
  }
  if (p === '/api/admin/stats' && m === 'GET') {
    const [cm, ch, rd, pays] = await env.DB.batch([
      env.DB.prepare(`SELECT COUNT(*) AS n FROM comics`), env.DB.prepare(`SELECT COUNT(*) AS n FROM chapters`),
      env.DB.prepare(`SELECT sub_expires FROM users WHERE role='reader'`), env.DB.prepare(`SELECT currency, SUM(amount) AS total, COUNT(*) AS n FROM payments WHERE status='success' GROUP BY currency`),
    ]);
    const revenue = {}; let n = 0;
    pays.results.forEach(r => { revenue[r.currency] = r.total; n += r.n; });
    return json({
      mode: payMode(env), comics: cm.results[0].n, chapters: ch.results[0].n, readers: rd.results.length,
      activeSubscribers: rd.results.filter(r => r.sub_expires && new Date(r.sub_expires).getTime() > Date.now()).length, payments: n, revenue,
    });
  }
  if (p === '/api/admin/users' && m === 'GET') {
    const { results } = await env.DB.prepare(`SELECT * FROM users WHERE role='reader' ORDER BY created_at DESC`).all();
    return json(results.map(publicUser));
  }
  if (p === '/api/admin/payments' && m === 'GET') {
    const { results } = await env.DB.prepare(`SELECT * FROM payments ORDER BY created_at DESC LIMIT 500`).all();
    return json(results.map(paymentOut));
  }
  if ((mt = p.match(/^\/api\/admin\/users\/([\w-]+)\/(grant|revoke)$/)) && m === 'POST') {
    const u = await env.DB.prepare(`SELECT * FROM users WHERE id=?`).bind(mt[1]).first();
    if (!u) return err('User not found.', 404);
    if (mt[2] === 'grant') {
      const days = Math.max(1, Math.min(3650, Number((await readBody(req)).days) || 30));
      await activate(env, u, { id: 'manual', name: `Manual (${days} days)`, days });
    } else {
      await env.DB.prepare(`UPDATE users SET sub_plan=NULL, sub_plan_name=NULL, sub_started=NULL, sub_expires=NULL WHERE id=?`).bind(u.id).run();
      Object.assign(u, { sub_expires: null });
    }
    return json(publicUser(u));
  }
  return err('Not found.', 404);
}

const validKey = (k, prefix) => typeof k === 'string' && k.startsWith(prefix) && /^[a-z]+\/[a-f0-9]+\.[a-z0-9]+$/.test(k) ? k : null;
const paymentOut = p => ({
  id: p.id, reference: p.reference, userId: p.user_id, userEmail: p.user_email, plan: p.plan, planName: p.plan_name, method: p.method,
  methodName: p.method_name, phone: p.phone, amount: p.amount, currency: p.currency, status: p.status, mode: p.mode, createdAt: p.created_at, paidAt: p.paid_at,
});

// Public images (covers & banners). PDFs are NEVER served here.
async function handleFiles(env, url) {
  const key = decodeURIComponent(url.pathname.slice('/files/'.length));
  if (!/^(covers|banners)\/[a-f0-9]+\.[a-z0-9]+$/.test(key)) return new Response('Not found', { status: 404 });
  const obj = await env.FILES.get(key);
  if (!obj) return new Response('Not found', { status: 404 });
  return new Response(obj.body, { headers: { 'Content-Type': (obj.httpMetadata && obj.httpMetadata.contentType) || 'image/jpeg', 'Cache-Control': 'public, max-age=604800' } });
}

function servePage(url) {
  const p = url.pathname === '/' ? '/index.html' : url.pathname;
  const f = PAGES[p] || PAGES[p + '.html'];
  if (!f) return null;
  return new Response(f.body, { headers: { 'Content-Type': f.type, 'Cache-Control': f.type.startsWith('text/html') ? 'no-cache' : 'public, max-age=3600' } });
}

const SETUP_PAGE = msg => new Response(`<!doctype html><meta name=viewport content="width=device-width,initial-scale=1"><body style="font-family:system-ui;background:#0d0d17;color:#fff;padding:2rem;line-height:1.6">
<h1>Morgan.stdio: setup needed</h1><p>${msg}</p></body>`, { status: 500, headers: { 'Content-Type': 'text/html; charset=utf-8' } });

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    try {
      if (req.method === 'GET' || req.method === 'HEAD') {
        const page = servePage(url);
        if (page) return page;
      }
      if (!env.DB || !env.FILES) return SETUP_PAGE('The database (DB) or file storage (FILES) is not connected to this Worker yet. Check the bindings in your Cloudflare Worker settings.');
      await init(env);
      if (url.pathname.startsWith('/api/')) return await handleApi(req, env, url);
      if (url.pathname.startsWith('/files/')) return await handleFiles(env, url);
      return new Response('Page not found', { status: 404 });
    } catch (e) {
      console.error(e && e.stack || e);
      return url.pathname.startsWith('/api/') ? err('Server error: ' + (e && e.message || e), 500) : SETUP_PAGE('Error: ' + String(e && e.message || e));
    }
  },
};
